window.__OPENSTAX_PHYSICS__[5] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:33:30.660Z","number":5,"code":"ch05","slug":"motion-in-two-dimensions","title":"Motion in Two Dimensions","titleVi":"Chuyển Động 2 Chiều, Mặt Phẳng Nghiêng & Dao Động Điều Hòa (2D Motion)","sections":[{"uid":"hsphys.ch05.sec00","moduleId":"m54145","number":"5.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch05.sec00.sub01","title":"Chapter Introduction","summaryVi":null,"paragraphs":["In Chapter 2, we learned to distinguish between vectors and scalars; the difference being that a vector has magnitude and direction, whereas a scalar has only magnitude and possibly sign. We learned how to deal with vectors in physics by working straightforward one-dimensional vector problems, which may be treated mathematically in the same as scalars. In this chapter, we’ll use vectors to expand our understanding of forces and motion into two dimensions. Most real-world physics problems (such as with the game of pool pictured here) are, after all, either two- or three-dimensional problems and physics is most useful when applied to real physical scenarios. We start by learning the practical skills of graphically adding and subtracting vectors (by using drawings) and analytically (with math). Once we’re able to work with two-dimensional vectors, we apply these skills to problems of projectile motion, inclined planes, and harmonic motion."],"figures":[{"sourceId":"fs-id1164355657079","filename":"CNX_HSPhysics_05_00_pooltable.jpg","relativePath":"media/CNX_HSPhysics_05_00_pooltable.jpg","alt":"Billiard balls in two-dimensional motion after the initial shot."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch05.sec01","moduleId":"m54165","number":"5.1","slug":"vector-addition-and-subtraction-graphical-methods","title":"Vector Addition and Subtraction: Graphical Methods","isIntroduction":false,"learningObjectives":["Describe the graphical method of vector addition and subtraction","Use the graphical method of vector addition and subtraction to solve physics problems"],"bilingualGuide":{"notebookSummaryVi":"Cộng trừ vectơ bằng phương pháp đồ họa (quy tắc nối đuôi–đầu Head-to-Tail).","wordProblemCues":[{"phraseEn":"resultant vector","meaningVi":"Vectơ tổng hợp","mathNotation":"R = A + B"}],"commonTrapsVi":["Thứ tự cộng vectơ không làm đổi kết quả (giao hoán: A + B = B + A)."]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch05.sec01.sub01","title":"The Graphical Method of Vector Addition and Subtraction","summaryVi":null,"paragraphs":["Recall that a vector is a quantity that has magnitude and direction. For example, displacement, velocity, acceleration, and force are all vectors. In one-dimensional or straight-line motion, the direction of a vector can be given simply by a plus or minus sign. Motion that is forward, to the right, or upward is usually considered to be positive (+); and motion that is backward, to the left, or downward is usually considered to be negative (-).","In two dimensions, a vector describes motion in two perpendicular directions, such as vertical and horizontal. For vertical and horizontal motion, each vector is made up of vertical and horizontal components. In a one-dimensional problem, one of the components simply has a value of zero. For two-dimensional vectors, we work with vectors by using a frame of reference such as a coordinate system. Just as with one-dimensional vectors, we graphically represent vectors with an arrow having a length proportional to the vector’s magnitude and pointing in the direction that the vector points.","[Figure 5.1] shows a graphical representation of a vector; the total displacement for a person walking in a city. The person first walks nine blocks east and then five blocks north. Her total displacement does not match her path to her final destination. The displacement simply connects her starting point with her ending point using a straight line, which is the shortest distance. We use the notation that a boldface symbol, such as D , stands for a vector. Its magnitude is represented by the symbol in italics, D , and its direction is given by an angle represented by the symbol \\(\\theta .\\) Note that her displacement would be the same if she had begun by first walking five blocks north and then walking nine blocks east.","The head-to-tail method is a graphical way to add vectors. The tail of the vector is the starting point of the vector, and the head (or tip) of a vector is the pointed end of the arrow. The following steps describe how to use the head-to-tail method for graphical vector addition .","Vector subtraction is done in the same way as vector addition with one small change. We add the first vector to the negative of the vector that needs to be subtracted. A negative vector has the same magnitude as the original vector, but points in the opposite direction (as shown in [Figure 5.1]). Subtracting the vector B from the vector A , which is written as A - B , is the same as A + (- B ). Since it does not matter in what order vectors are added, A - B is also equal to (- B ) + A . This is true for scalars as well as vectors. For example, 5 – 2 = 5 + (-2) = (-2) + 5.","Global angles are calculated in the counterclockwise direction. The clockwise direction is considered negative. For example, an angle of \\({30}^{∘}\\) south of west is the same as the global angle \\({210}^{∘},\\) which can also be expressed as \\({-150}^{∘}\\) from the positive x -axis."],"figures":[{"sourceId":"fs-id1167065859280","filename":"CNX_HSPhysics_05_01_city.jpg","relativePath":"media/CNX_HSPhysics_05_01_city.jpg","alt":"A map is shown over top x and y-axes. The origin is labeled Starting Point. The x-axis represents east and has a scale from zero to nine in increments of one. The y-axis represents north and has a scale from zero to five in increments of one. Lines show that a person walks nine blocks east and five blocks north. A displacement vector is plotted from the origin to the destination of nine, five on the axes."},{"sourceId":"fs-id1167065763661","filename":"CNX_HSPhysics_05_01_vector(a).jpg","relativePath":"media/CNX_HSPhysics_05_01_vector(a).jpg","alt":"The diagram shows a vector along an x-axis with a magnitude of nine units and a direction of 0°. An unlabeled y-axis is also shown."},{"sourceId":"fs-id1167065764637","filename":"CNX_HSPhysics_05_01_vector(b).jpg","relativePath":"media/CNX_HSPhysics_05_01_vector(b).jpg","alt":"The diagram shows a vector along an x-axis with a magnitude of nine units and a direction of 0°. A vertical vector is also shown at nine units with a height of five units. A y-axis is also shown with ten tick marks."},{"sourceId":"fs-id1167065785430","filename":"CNX_HSPhysics_05_01_vector(c).jpg","relativePath":"media/CNX_HSPhysics_05_01_vector(c).jpg","alt":"The diagram shows a vector along an x-axis with a magnitude of nine units and a direction of 0°. A vertical vector is also shown at nine units with a height of five units. A y-axis is shown with ten tick marks. A resultant vector is drawn, forming a right triangle with the other two vectors. This vector is labeled D, has a magnitude of ten point three units, and forms a twenty-nine point one degree angle with the x-axis."},{"sourceId":"fs-id1167066034916","filename":"CNX_HSPhysics_05_01_negative.jpg","relativePath":"media/CNX_HSPhysics_05_01_negative.jpg","alt":"Two vectors are shown. Vector B points upward at an angle. Vector negative B is parallel to vector B and points downward."}],"tables":[]},{"uid":"hsphys.ch05.sec01.sub02","title":"Using the Graphical Method of Vector Addition and Subtraction to Solve Physics Problems","summaryVi":null,"paragraphs":["Now that we have the skills to work with vectors in two dimensions, we can apply vector addition to graphically determine the resultant vector , which represents the total force. Consider an example of force involving two ice skaters pushing a third as seen in [Figure 5.1].","In problems where variables such as force are already known, the forces can be represented by making the length of the vectors proportional to the magnitudes of the forces. For this, you need to create a scale. For example, each centimeter of vector length could represent 50 N worth of force. Once you have the initial vectors drawn to scale, you can then use the head-to-tail method to draw the resultant vector. The length of the resultant can then be measured and converted back to the original units using the scale you created.","You can tell by looking at the vectors in the free-body diagram in [Figure 5.1] that the two skaters are pushing on the third skater with equal-magnitude forces, since the length of their force vectors are the same. Note, however, that the forces are not equal because they act in different directions. If, for example, each force had a magnitude of 400 N, then we would find the magnitude of the total external force acting on the third skater by finding the magnitude of the resultant vector. Since the forces act at a right angle to one another, we can use the Pythagorean theorem. For a triangle with sides a, b, and c, the Pythagorean theorem tells us that","Applying this theorem to the triangle made by F 1 , F 2 , and F tot in [Figure 5.1], we get","or","Note that, if the vectors were not at a right angle to each other \\(({90}^{∘}\\)\nto one another), we would not be able to use the Pythagorean theorem to find the magnitude of the resultant vector. Another scenario where adding two-dimensional vectors is necessary is for velocity, where the direction may not be purely east-west or north-south, but some combination of these two directions. In the next section, we cover how to solve this type of problem analytically. For now let’s consider the problem graphically."],"figures":[{"sourceId":"fs-id1167065974680","filename":"CNX_HSPhysics_05_01_skaters.jpg","relativePath":"media/CNX_HSPhysics_05_01_skaters.jpg","alt":"Two diagrams are shown. Diagram a is an overhead view of two skaters, one on the left and one below, pushing on a third skater in the center. A force vector is shown on each of the pushing skaters pointing from the skater's shoulder to the skater in the center. A right triangle is drawn using the force vectors, with F tot as the hypotenuse, F one as the bottom leg, and F two as the right leg. Diagram b is a free body diagram with F one pointing to the right and F two pointing up. Both vectors have the same magnitude."}],"tables":[]},{"uid":"hsphys.ch05.sec01.sub03","title":"Vector Addition","summaryVi":null,"paragraphs":["In this simulation , you will experiment with adding vectors graphically. Click and drag the red vectors from the Grab One basket onto the graph in the middle of the screen. These red vectors can be rotated, stretched, or repositioned by clicking and dragging with your mouse. Check the Show Sum box to display the resultant vector (in green), which is the sum of all of the red vectors placed on the graph. To remove a red vector, drag it to the trash or click the Clear All button if you wish to start over. Notice that, if you click on any of the vectors, the \\(|\\mathbf{R}|\\) is its magnitude, \\(\\theta\\) is its direction with respect to the positive x -axis, R x is its horizontal component, and R y is its vertical component. You can check the resultant by lining up the vectors so that the head of the first vector touches the tail of the second. Continue until all of the vectors are aligned together head-to-tail. You will see that the resultant magnitude and angle is the same as the arrow drawn from the tail of the first vector to the head of the last vector. Rearrange the vectors in any order head-to-tail and compare. The resultant will always be the same.","True or FalseThe more long, red vectors you put on the graph, rotated in any direction, the greater the magnitude of the resultant green vector."],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch05.sec01.ex01","number":"5.1.1","title":"Adding Vectors Graphically by Using the Head-to-Tail Method: A Woman Takes a Walk","problem":"Use the graphical technique for adding vectors to find the total displacement of a person who walks the following three paths (displacements) on a flat field. First, she walks 25 m in a direction \\({49}^{∘}\\) north of east. Then, she walks 23 m heading \\({15}^{∘}\\) north of east. Finally, she turns and walks 32 m in a direction \\({68}^{∘}\\) south of east.","problemImages":[],"strategy":"Graphically represent each displacement vector with an arrow, labeling the first A , the second B , and the third C . Make the lengths proportional to the distance of the given displacement and orient the arrows as specified relative to an east-west line. Use the head-to-tail method outlined above to determine the magnitude and direction of the resultant displacement, which we’ll call R .","solution":"(1) Draw the three displacement vectors, creating a convenient scale (such as 1 cm of vector length on paper equals 1 m in the problem), as shown in [Figure 5.1].\nThe three displacement vectors are drawn first.\n(2) Place the vectors head to tail, making sure not to change their magnitude or direction, as shown in [Figure 5.1].\nNext, the vectors are placed head to tail.\n(3) Draw the resultant vector R from the tail of the first vector to the head of the last vector, as shown in [Figure 5.1].\nThe resultant vector is drawn .\n(4) Use a ruler to measure the magnitude of R , remembering to convert back to the units of meters using the scale. Use a protractor to measure the direction of R . While the direction of the vector can be specified in many ways, the easiest way is to measure the angle between the vector and the nearest horizontal or vertical axis. Since R is south of the eastward pointing axis (the x -axis), we flip the protractor upside down and measure the angle between the eastward axis and the vector, as illustrated in [Figure 5.1].\nA ruler is used to measure the magnitude of R , and a protractor is used to measure the direction of R .\nIn this case, the total displacement R has a magnitude of 50 m and points \\({7}^{∘}\\) south of east. Using its magnitude and direction, this vector can be expressed as\nR =  50  m\nand\n\\(\\theta = {7}^{∘}\\text{south of east.}\\)","solutionImages":[{"sourceId":"fs-id1167065865132","filename":"CNX_HSPhysics_05_01_displace.jpg","relativePath":"media/CNX_HSPhysics_05_01_displace.jpg","alt":"Three displacement vectors are drawn on separate x-y axes. Vector A points upward from the origin and is twenty-five meters with an angle of forty-nine degrees. Vector B points upward from the origin and is twenty-three meters with an angle of fifteen degrees. Vector C points downward from the origin and is thirty-two meters with an angle of sixty-eight degrees."},{"sourceId":"fs-id1167065839060","filename":"CNX_HSPhysics_05_01_tall.jpg","relativePath":"media/CNX_HSPhysics_05_01_tall.jpg","alt":"Three vectors, A, B, and C are shown. They form three sides of a polygon, with an x-axis forming the fourth side. The arrow of vector A touches the end of vector B and has an x-y-axis shown at the touching point. The arrow of vector B touches the end of vector C and has an x-y-axis shown at the touching point."},{"sourceId":"fs-id1167066037227","filename":"CNX_HSPhysics_05_01_result.jpg","relativePath":"media/CNX_HSPhysics_05_01_result.jpg","alt":"Vectors A, B, C, and R form a four-sided figure, with vector R intersecting an x-axis. The magnitude of vector R is fifty meters and vector R forms a seven degree angle with the x-axis."},{"sourceId":"fs-id1167065714918","filename":"CNX_HSPhysics_05_01_measure.jpg","relativePath":"media/CNX_HSPhysics_05_01_measure.jpg","alt":"Vectors A, B, C, and R form a four-sided figure, with vector R intersecting an x-axis. A ruler and a protractor are pictured below the figure. The magnitude of vector R is fifty meters and the direction of vector R is ninety degrees."}],"solutionTables":[],"discussion":"The head-to-tail graphical method of vector addition works for any number of vectors. It is also important to note that it does not matter in what order the vectors are added. Changing the order does not change the resultant. For example, we could add the vectors as shown in [Figure 5.1], and we would still get the same solution.\nVectors can be added in any order to get the same result."},{"uid":"hsphys.ch05.sec01.ex02","number":"5.1.2","title":"Subtracting Vectors Graphically: A Woman Sailing a Boat","problem":"A woman sailing a boat at night is following directions to a dock. The instructions read to first sail 27.5 m in a direction \\({66.0}^{∘}\\) north of east from her current location, and then travel 30.0 m in a direction \\({112}^{∘}\\) north of east (or \\({22.0}^{∘}\\) west of north). If the woman makes a mistake and travels in the opposite direction for the second leg of the trip, where will she end up? The two legs of the woman’s trip are illustrated in [Figure 5.1].\nIn the diagram, the first leg of the trip is represented by vector A and the second leg is represented by vector B.","problemImages":[{"sourceId":"fs-id1167065885132","filename":"CNX_HSPhysics_05_01_magnitude.jpg","relativePath":"media/CNX_HSPhysics_05_01_magnitude.jpg","alt":"An x-y axis is shown for reference. Vector A points upward from the x-axis is twenty-seven point five meters, and has an angle of sixty-six degrees. Vector B points upward from the x-axis is thirty meters, and has an angle of one hundred twelve degrees."}],"strategy":"We can represent the first leg of the trip with a vector A , and the second leg of the trip that she was supposed to take with a vector B . Since the woman mistakenly travels in the opposite direction for the second leg of the journey, the vector for second leg of the trip she actually takes is - B . Therefore, she will end up at a location A + (- B ), or A - B . Note that - B has the same magnitude as B (30.0 m), but is in the opposite direction, \\({68}^{∘}({180}^{∘} - {112}^{∘})\\) south of east, as illustrated in [Figure 5.1].\nVector –B represents traveling in the opposite direction of vector B.\nWe use graphical vector addition to find where the woman arrives A + (- B ).","solution":"(1) To determine the location at which the woman arrives by accident, draw vectors A and - B .\n(2) Place the vectors head to tail.\n(3) Draw the resultant vector R .\n(4) Use a ruler and protractor to measure the magnitude and direction of R .\nThese steps are demonstrated in [Figure 5.1].\nThe vectors are placed head to tail.\nIn this case\n\\(R = 23.0\\,\\text{m}\\)\nand\n\\(\\theta = 7.5°\\text{south of east.}\\)","solutionImages":[{"sourceId":"fs-id1167065770877","filename":"CNX_HSPhysics_05_01_connected.jpg","relativePath":"media/CNX_HSPhysics_05_01_connected.jpg","alt":"An x-y axis is shown on the left. On the right, vectors A, negative B, and R form a triangle. R and the x-axis form an angle with a measure of seven point five degrees. A minus B equals R and R equals twenty-three meters."}],"solutionTables":[],"discussion":"Because subtraction of a vector is the same as addition of the same vector with the opposite direction, the graphical method for subtracting vectors works the same as for adding vectors."},{"uid":"hsphys.ch05.sec01.ex03","number":"5.1.3","title":"Adding Velocities: A Boat on a River","problem":"A boat attempts to travel straight across a river at a speed of 3.8 m/s. The river current flows at a speed v river of 6.1 m/s to the right. What is the total velocity and direction of the boat? You can represent each meter per second of velocity as one centimeter of vector length in your drawing.","problemImages":[],"strategy":"We start by choosing a coordinate system with its x-axis parallel to the velocity of the river. Because the boat is directed straight toward the other shore, its velocity is perpendicular to the velocity of the river. We draw the two vectors, v boat and v river , as shown in [Figure 5.1].\nUsing the head-to-tail method, we draw the resulting total velocity vector from the tail of v boat to the head of v river .\nA boat attempts to travel across a river. What is the total velocity and direction of the boat?","solution":"By using a ruler, we find that the length of the resultant vector is 7.2 cm, which means that the magnitude of the total velocity is\n\\({\\text{v}}_{\\text{tot}} = 7.2\\,\\text{m/s}.\\)\nBy using a protractor to measure the angle, we find \\(\\theta = {32.0}^{∘}\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"If the velocity of the boat and river were equal, then the direction of the total velocity would have been 45°. However, since the velocity of the river is greater than that of the boat, the direction is less than 45° with respect to the shore, or x axis."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch05.sec01.feat01","type":"tip","title":"Tips for Success","text":"In this text, we represent a vector with a boldface variable. For example, we represent a force with the vector F , which has both magnitude and direction. The magnitude of the vector is represented by the variable in italics, F , and the direction of the variable is given by the angle \\(\\theta .\\)","images":[]}],"summaryPoints":["The graphical method of adding vectors \\(\\text{A}\\) and \\(\\mathbf{B}\\) involves drawing vectors on a graph and adding them by using the head-to-tail method. The resultant vector \\(\\mathbf{R}\\) is defined such that A + B = R . The magnitude and direction of \\(\\text{R}\\) are then determined with a ruler and protractor.","The graphical method of subtracting vectors A and B involves adding the opposite of vector B , which is defined as - B . In this case, \\(\\mathbf{A}–\\mathbf{B} = \\mathbf{A} + (–\\mathbf{B}) = \\mathbf{R}.\\) Next, use the head-to-tail method as for vector addition to obtain the resultant vector \\(\\text{R}\\) .","Addition of vectors is independent of the order in which they are added; A + B = B + A .","The head-to-tail method of adding vectors involves drawing the first vector on a graph and then placing the tail of each subsequent vector at the head of the previous vector. The resultant vector is then drawn from the tail of the first vector to the head of the final vector.","Variables in physics problems, such as force or velocity, can be represented with vectors by making the length of the vector proportional to the magnitude of the force or velocity.","Problems involving displacement, force, or velocity may be solved graphically by measuring the resultant vector’s magnitude with a ruler and measuring the direction with a protractor."],"glossary":[{"term":"graphical method","termVi":"Phương pháp đồ họa (cộng vectơ)","definition":"drawing vectors on a graph to add them using the head-to-tail method","definitionVi":"Cộng vectơ bằng cách vẽ đúng tỉ lệ độ dài và góc (quy tắc nối đuôi đầu).","memoryTipVi":"Head-to-tail method."},{"term":"head (of a vector)","termVi":"Ngọn (đầu mũi tên) vectơ","definition":"the end point of a vector; the location of the vector’s arrow; also referred to as the tip","definitionVi":"Đầu có mũi tên chỉ hướng của vectơ.","memoryTipVi":"Tail = gốc, Head = ngọn."},{"term":"head-to-tail method","termVi":"Quy tắc cộng vectơ nối đuôi – đầu","definition":"a method of adding vectors in which the tail of each vector is placed at the head of the previous vector","definitionVi":"Đặt gốc vectơ sau vào ngọn vectơ trước; vectơ tổng nối từ gốc đầu đến ngọn cuối.","memoryTipVi":"Cộng được nhiều vectơ liên tiếp một cách trực quan."},{"term":"resultant","termVi":"Vectơ tổng hợp","definition":"the sum of the a collection of vectors","definitionVi":"Kết quả của phép cộng hai hay nhiều vectơ.","memoryTipVi":"Ký hiệu thường là R."},{"term":"resultant vector","termVi":"Vectơ tổng hợp","definition":"the vector sum of two or more vectors","definitionVi":"Vectơ duy nhất có tác dụng tương đương tổng các vectơ thành phần.","memoryTipVi":"R = √(R_x² + R_y²)."},{"term":"tail","termVi":"Gốc (đuôi) vectơ","definition":"the starting point of a vector; the point opposite to the head or tip of the arrow","definitionVi":"Điểm xuất phát của một mũi tên vectơ.","memoryTipVi":"Gốc đặt tại điểm đặt lực."},{"term":"vector addition","termVi":"Phép cộng vectơ","definition":"adding together two or more vectors","definitionVi":"Cộng hai hay nhiều vectơ theo quy tắc hình học hoặc cộng từng thành phần x, y.","memoryTipVi":"Không được cộng độ lớn số học đơn thuần trừ khi chúng cùng hướng!"}],"assessments":[{"uid":"hsphys.ch05.sec01.q002","sourceId":"fs-id1167066983659","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"True or FalseA person walks 2 blocks east and 5 blocks north. Another person walks 5 blocks north and then two blocks east. The displacement of the first person will be more than the displacement of the second person.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec01.q005","sourceId":"fs-id1167065869663","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"There is a vector \\(\\vec{\\text{A}}\\), with magnitude 5 units pointing towards west and vector \\(\\vec{\\text{B}}\\), with magnitude 3 units, pointing towards south. Using vector addition, calculate the magnitude of the resultant vector.","images":[],"choices":[{"label":"a","text":"4.0"},{"label":"b","text":"5.8"},{"label":"c","text":"6.3"},{"label":"d","text":"8.0"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec01.q008","sourceId":"fs-id1167065855128","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"True or FalseA person is following a set of directions. He has to walk 2 km east and then 1 km north. He takes a wrong turn and walks in the opposite direction for the second leg of the trip. The magnitude of his total displacement will be the same as it would have been had he followed directions correctly.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec01.q013","sourceId":"fs-id1167065864701","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"True or False—We can use Pythagorean theorem to calculate the length of the resultant vector obtained from the addition of two vectors which are at right angles to each other.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec01.q014","sourceId":"fs-id1167066047872","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"True or FalseThe direction of the resultant vector depends on both the magnitude and direction of added vectors.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec01.q019","sourceId":"fs-id1167065859455","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Consider six vectors of 2 cm each, joined from head to tail making a hexagon. What would be the magnitude of the addition of these vectors?","images":[],"choices":[{"label":"a","text":"Zero"},{"label":"b","text":"Six"},{"label":"c","text":"Eight"},{"label":"d","text":"Twelve"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec01.q020","sourceId":"fs-id1167065871032","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Two people pull on ropes tied to a trolley, each applying 44 N of force. The angle the ropes form with each other is 39.5°. What is the magnitude of the net force exerted on the trolley?","images":[],"choices":[{"label":"a","text":"0.0 N"},{"label":"b","text":"79.6 N"},{"label":"c","text":"82.8 N"},{"label":"d","text":"88.0 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec01.q021","sourceId":"fs-id1167065850650","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"True or False—For vectors the order of addition is important.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec01.q022","sourceId":"fs-id1167065875808","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Consider five vectors a, b, c, d, and e. Is it true or false that their addition always results in a vector with a greater magnitude than if only two of the vectors were added?","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":0,"subsectionCount":3,"workedExampleCount":3,"snapLabCount":0,"glossaryCount":7,"assessmentCount":9}},{"uid":"hsphys.ch05.sec02","moduleId":"m54147","number":"5.2","slug":"vector-addition-and-subtraction-analytical-methods","title":"Vector Addition and Subtraction: Analytical Methods","isIntroduction":false,"learningObjectives":["Define components of vectors","Describe the analytical method of vector addition and subtraction","Use the analytical method of vector addition and subtraction to solve problems"],"bilingualGuide":{"notebookSummaryVi":"Cộng vectơ bằng phương pháp giải tích: chiếu lên trục Ox (cosθ), Oy (sinθ) rồi dùng Pythagoras tìm độ lớn R = √(R_x² + R_y²).","wordProblemCues":[{"phraseEn":"resolve into components","meaningVi":"Phân tích vectơ thành 2 thành phần x, y","mathNotation":"A_x = A cosθ"}],"commonTrapsVi":["Luôn kiểm tra góc θ đo so với trục ngang hay trục đứng trước khi bấm sin/cos!"]},"keyEquations":[{"name":"resultant magnitude","formula":"\\(R = \\sqrt{{R}_{x}^{2} + {R}_{y}^{2}}\\)"},{"name":"resultant direction","formula":"\\(\\theta = {\\text{tan}}^{- 1}({R}_{y}/{R}_{x})\\)"},{"name":"x-component of a vector A (when an angle is given relative to the horizontal)","formula":"\\({A}_{x} = A\\text{cos}\\theta\\)"},{"name":"y-component of a vector A (when an angle is given relative to the horizontal)","formula":"\\({A}_{y} = A\\text{sin}\\theta\\)"},{"name":"addition of vectors","formula":"\\({\\mathbf{A}}_{\\mathbf{x}} + {\\mathbf{A}}_{\\mathbf{y}} = \\mathbf{A}\\)"}],"subsections":[{"uid":"hsphys.ch05.sec02.sub01","title":"Components of Vectors","summaryVi":null,"paragraphs":["For the analytical method of vector addition and subtraction, we use some simple geometry and trigonometry, instead of using a ruler and protractor as we did for graphical methods. However, the graphical method will still come in handy to visualize the problem by drawing vectors using the head-to-tail method. The analytical method is more accurate than the graphical method, which is limited by the precision of the drawing. For a refresher on the definitions of the sine, cosine, and tangent of an angle, see [Figure 5.2].","Since, by definition, \\(\\text{cos}\\theta = x/h\\), we can find the length x if we know h and \\(\\theta\\) by using \\(x = h\\text{cos}\\theta\\) . Similarly, we can find the length of y by using \\(y = h\\text{sin}\\theta\\) . These trigonometric relationships are useful for adding vectors.","When a vector acts in more than one dimension, it is useful to break it down into its x and y components. For a two-dimensional vector, a component is a piece of a vector that points in either the x- or y-direction. Every 2-d vector can be expressed as a sum of its x and y components.","For example, given a vector like \\(\\mathbf{A}\\) in [Figure 5.2], we may want to find what two perpendicular vectors, \\({\\mathbf{A}}_{x}\\) and \\({\\mathbf{A}}_{y}\\), add to produce it. In this example, \\({\\mathbf{A}}_{x}\\) and \\({\\mathbf{A}}_{y}\\) form a right triangle, meaning that the angle between them is 90 degrees. This is a common situation in physics and happens to be the least complicated situation trigonometrically.","\\({\\mathbf{A}}_{x}\\) and \\({\\mathbf{A}}_{y}\\) are defined to be the components of \\(\\mathbf{A}\\) along the x - and y -axes. The three vectors, \\(\\mathbf{A}\\), \\({\\mathbf{A}}_{x}\\), and \\({\\mathbf{A}}_{y}\\), form a right triangle.","If the vector \\(\\mathbf{A}\\) is known, then its magnitude \\(A\\) (its length) and its angle \\(\\theta\\) (its direction) are known. To find \\({A}_{x}\\) and \\({A}_{y}\\), its x - and y -components, we use the following relationships for a right triangle:","and","where \\({A}_{x}\\) is the magnitude of A in the x -direction, \\({A}_{y}\\) is the magnitude of A in the y -direction, and \\(\\theta\\) is the angle of the resultant with respect to the x -axis, as shown in [Figure 5.2].","Suppose, for example, that \\(\\mathbf{A}\\) is the vector representing the total displacement of the person walking in a city, as illustrated in [Figure 5.2].","Then A = 10.3 blocks and \\(\\theta = {29.1}^{∘}\\), so that","This magnitude indicates that the walker has traveled 9 blocks to the east—in other words, a 9-block eastward displacement. Similarly,","indicating that the walker has traveled 5 blocks to the north—a 5-block northward displacement."],"figures":[{"sourceId":"fs-id1167067022005","filename":"CNX_HSPhysics_05_02_trig.jpg","relativePath":"media/CNX_HSPhysics_05_02_trig.jpg","alt":"A right triangle is shown. The hypotenuse is labeled h, the vertical leg is labeled Y, and the horizontal leg is labeled X. The right angle is labeled with the angle symbol. The following formulas appear next to the triangle: sine angle equals y over h, cosine angle equals x over h, and tangent angle equals y over x."},{"sourceId":"fs-id1167067041459","filename":"CNX_HSPhysics_05_02_right.jpg","relativePath":"media/CNX_HSPhysics_05_02_right.jpg","alt":"Vectors A, Ax, and Ay are shown. The vector A, with its tail at the origin of an x, y-coordinate system, is shown together with its x- and y-components, Ax and Ay. These vectors form a right triangle. The formula Ax plus Ay equals A is shown above the vectors."},{"sourceId":"fs-id1167066864263","filename":"CNX_HSPhysics_05_02_angle.jpg","relativePath":"media/CNX_HSPhysics_05_02_angle.jpg","alt":"Vectors A x and A y form the legs of a right triangle and vector A forms the hypotenuse. Vector Ax is along an x-axis and vector Y is vertical and dashed. A x equals A times cosine angle. A y equals A times sine angle. A x plus A y equals A."},{"sourceId":"fs-id1167067024738","filename":"CNX_HSPhysics_05_02_blocks.jpg","relativePath":"media/CNX_HSPhysics_05_02_blocks.jpg","alt":"A map is shown over top x and y-axes. The origin is labeled Starting Point. The x-axis represents east and has a scale from zero to nine in increments of one. The y-axis represents north and has a scale from zero to five in increments of one. Lines show that a person walks nine blocks east and five blocks north. A displacement vector is plotted from the origin to the destination of nine, five on the axes. The following label is next to the y-axis: A y equals A times sine angle, equals ten point three blocks times sine twenty-nine point one, equals five blocks north. The following label is next to the x-axis: A x equals A cosine angle, equals ten point three blocks times sine twenty-nine point one, equals nine blocks east."}],"tables":[]},{"uid":"hsphys.ch05.sec02.sub02","title":"Analytical Method of Vector Addition and Subtraction","summaryVi":null,"paragraphs":["Calculating a resultant vector (or vector addition) is the reverse of breaking the resultant down into its components. If the perpendicular components \\({\\mathbf{A}}_{x}\\) and \\({\\mathbf{A}}_{y}\\) of a vector \\(\\mathbf{A}\\) are known, then we can find \\(\\mathbf{A}\\) analytically. How do we do this? Since, by definition,","we solve for \\(\\theta\\) to find the direction of the resultant.","Note that \\({\\text{tan}}^{- 1}(\\theta )\\) gives an angle in the first quadrant if\n\\({A}_{y}/{A}_{x}\\, \\gt \\,0\\) and in the fourth quadrant if\n\\({A}_{y}/{A}_{x}\\, \\lt \\,0\\). If, in fact, both \\({A}_{x}\\) and \\({A}_{y}\\) are negative, or if \\({A}_{x}\\) is negative and \\({A}_{y}\\) positive, then \\(\\theta\\), measured from the positive \\(x\\) direction, is\n\\({\\text{tan}}^{–1}(\\theta ) + 180\\text{°}\\).","Since this is a right triangle, the Pythagorean theorem (x 2 + y 2 = h 2 ) for finding the hypotenuse applies. In this case, it becomes","Solving for A gives","In summary, to find the magnitude \\(A\\) and direction \\(\\theta\\) of a vector from its perpendicular components \\({\\mathbf{A}}_{x}\\) and \\({\\mathbf{A}}_{y}\\), as illustrated in [Figure 5.2], we use the following relationships:","Sometimes, the vectors added are not perfectly perpendicular to one another. An example of this is the case below, where the vectors \\(\\mathbf{A}\\) and \\(\\mathbf{B}\\) are added to produce the resultant \\(\\mathbf{R}\\text{,}\\) as illustrated in [Figure 5.2].","If \\(\\mathbf{A}\\) and \\(\\mathbf{B}\\) represent two legs of a walk (two displacements), then \\(\\mathbf{R}\\) is the total displacement. The person taking the walk ends up at the tip of \\(\\mathbf{R}\\) . There are many ways to arrive at the same point. The person could have walked straight ahead first in the x -direction and then in the y -direction. Those paths are the x - and y -components of the resultant, \\({\\mathbf{R}}_{x}\\) and \\({\\mathbf{R}}_{y}.\\) If we know \\({\\mathbf{R}}_{x}\\) and \\({\\mathbf{R}}_{y}\\), we can find \\(R\\) and \\(\\theta\\) using the equations \\(R = \\sqrt{{R}_{\\text{x}}{}^{2} + {R}_{\\text{y}}{}^{2}}\\) and \\(\\theta = ta{n}^{–1}({R}_{y}/{R}_{x})\\) .","and find the y component of the resultant (as illustrated in [Figure 5.2]) by adding the y component of the vectors.","Now that we know the components of \\(\\mathbf{R},\\) we can find its magnitude and direction."],"figures":[{"sourceId":"fs-id1167067065839","filename":"CNX_HSPhysics_05_02_diagonal.jpg","relativePath":"media/CNX_HSPhysics_05_02_diagonal.jpg","alt":"Vectors Ax and Ay form the legs of a right triangle and vector A forms the hypotenuse. Vectors Ax and Ay are dashed. The formula angle equals inverse tangent times Ay over Ax is inside the triangle. Vector A is labeled A equals the square root of Ax squared plus Ay squared."},{"sourceId":"fs-id1167066841908","filename":"CNX_HSPhysics_05_02_direction.jpg","relativePath":"media/CNX_HSPhysics_05_02_direction.jpg","alt":"A compass is shown on the left. On the right, vectors A, B, and R form a triangle, with the vertex of AR at the origin of an x-y axis. The formula A plus B equals R is above the triangle."},{"sourceId":"fs-id1167067086808","filename":"CNX_HSPhysics_05_02_dotted.jpg","relativePath":"media/CNX_HSPhysics_05_02_dotted.jpg","alt":"A compass is shown on the left. On the right, vectors A, B, and R form a triangle, with the vertex of AR at the origin of an x-y axis. The formula A plus B equals R is above the triangle. Dashed lines indicate vertical and horizontal components of each vector. Labels indicate locations for angle A and angle B."},{"sourceId":"fs-id1167066983741","filename":"CNX_HSPhysics_05_02_R.jpg","relativePath":"media/CNX_HSPhysics_05_02_R.jpg","alt":"A compass is shown on the left. On the right, vectors A, B, and R form a triangle, with the vertex of AR at the origin of an x-y axis. The formula A plus B equals R is above the triangle. Dashed lines indicate vertical and horizontal components of each vector. Labels indicate locations for angle A and angle B. The formula Rx equals Ax plus Bx is below the x-axis. The formula Ry equals Ay plus By is next to the y-axis."}],"tables":[]},{"uid":"hsphys.ch05.sec02.sub03","title":"Using the Analytical Method of Vector Addition and Subtraction to Solve Problems","summaryVi":null,"paragraphs":["[Figure 5.2] uses the analytical method to add vectors."],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch05.sec02.ex01","number":"5.2.1","title":"An Accelerating Subway Train","problem":"Add the vector \\(\\mathbf{A}\\) to the vector \\(\\mathbf{B}\\) shown in [Figure 5.2], using the steps above. The x -axis is along the east–west direction, and the y -axis is along the north–south directions. A person first walks 53 .0 m in a direction 20 .0° north of east, represented by vector \\(\\mathbf{A}.\\) The person then walks 34 .0 m in a direction \\(\\text{63}\\text{.0}°\\) north of east, represented by vector \\(\\mathbf{B}.\\)\nYou can use analytical models to add vectors.","problemImages":[{"sourceId":"fs-id1167066946714","filename":"CNX_HSPhysics_05_02_AB.jpg","relativePath":"media/CNX_HSPhysics_05_02_AB.jpg","alt":"Vectors A, B, and R form a triangle with vertex RA at the origin of an x y-axis. The following labels are included: angle (where R and A form an angle) equals thirty-six point six degrees, angle A equals twenty degrees, angle B equals sixty-three degrees, A equals fifty-three meters, B equals thirty-four meters, and A plus B equals R. A compass is shown in the bottom corner for reference."}],"strategy":"The components of \\(\\mathbf{A}\\) and \\(\\mathbf{B}\\) along the x - and y -axes represent walking due east and due north to get to the same ending point. We will solve for these components and then add them in the x-direction and y-direction to find the resultant.","solution":"First, we find the components of \\(\\mathbf{A}\\) and \\(\\mathbf{B}\\) along the x - and y -axes. From the problem, we know that \\(A = 53.0\\,\\text{m,}\\) \\({\\theta}_{\\text{A}} = {20.0}^{∘,}\\) \\(B\\) = 34 .0 m, and \\({\\theta}_{\\text{B}} = {63.0}^{∘}\\) . We find the x -components by using \\({A}_{x} = Acos\\theta\\), which gives\n\\({A}_{x} = Acos{\\theta}_{A} = (53.0\\,\\text{m})(cos{20.0}^{∘}) = (53.0\\,\\text{m})(0.940) = 49.8\\,\\text{m}\\)\nand\n\\({B}_{x} = Bcos{\\theta}_{B} = (34.0\\,\\text{m})(cos{63.0}^{∘}) = (34.0\\,\\text{m})(0.454) = 15.4\\,\\text{m.}\\)\nSimilarly, the y -components are found using \\({A}_{y} = Asin{\\theta}_{A}\\)\n\\({A}_{y} = Asin{\\theta}_{A} = (53.0\\,\\text{m})(sin{20.0}^{∘}) = (53.0\\,\\text{m})(0.342) = 18.1\\,\\text{m}\\)\nand\n\\({B}_{y} = Bsin{\\theta}_{B} = (34.0\\,\\text{m})(sin{63.0}^{∘}) = (34.0\\,\\text{m})(0.891) = 30.3\\,\\text{m}\\text{.}\\)\nThe x - and y -components of the resultant are\n\\({R}_{x} = {A}_{x} + {B}_{x} = 49.8\\,\\text{m} + 15.4\\,\\text{m} = 65.2\\,\\text{m}\\)\nand\n\\({R}_{y} = {A}_{y} + {B}_{y} = 18.1\\,\\text{m} + 30.3\\,\\text{m} = 48.4\\,\\text{m}.\\)\nNow we can find the magnitude of the resultant by using the Pythagorean theorem\n\\(R = \\sqrt{{R}_{x}^{2} + {R}_{y}^{2}} = \\sqrt{{(65.2)}^{2} + {(48.4)}^{2}}\\text{m}\\)\nso that\n\\(R = \\sqrt{6601\\,\\text{m}} = 81.2\\,\\text{m}\\text{.}\\)\nFinally, we find the direction of the resultant\n\\(\\theta = {tan}^{- 1}({R}_{y}/{R}_{x}) = + {tan}^{- 1}(48.4/65.2).\\)\nThis is\n\\(\\theta = {tan}^{- 1}(0.742) = {36.6}^{∘}.\\)","solutionImages":[],"solutionTables":[],"discussion":"This example shows vector addition using the analytical method. Vector subtraction using the analytical method is very similar. It is just the addition of a negative vector. That is, \\(\\text{A} - \\text{B}≡\\text{A} + ( - \\text{B})\\) . The components of – B are the negatives of the components of B . Therefore, the x - and y -components of the resultant A - B = R are\n\\({R}_{x} = {A}_{x} + - {B}_{x}\\)\nand\n\\({R}_{y} = {A}_{y} + - {B}_{y}\\)\nand the rest of the method outlined above is identical to that for addition."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch05.sec02.feat01","type":"tip","title":"Tips for Success","text":"In the video, the vectors were represented with an arrow above them rather than in bold. This is a common notation in math classes.","images":[]},{"uid":"hsphys.ch05.sec02.feat02","type":"physics-in-action","title":"Atmospheric Science","text":"This picture shows Bert Foord during a television Weather Forecast from the Meteorological Office in 1963. (BBC TV) Atmospheric science is a physical science , meaning that it is a science based heavily on physics. Atmospheric science includes meteorology (the study of weather) and climatology (the study of climate). Climate is basically the average weather over a longer time scale. Weather changes quickly over time, whereas the climate changes more gradually.\nThe movement of air, water and heat is vitally important to climatology and meteorology. Since motion is such a major factor in weather and climate, this field uses vectors for much of its math.\nVectors are used to represent currents in the ocean, wind velocity and forces acting on a parcel of air. You have probably seen a weather map using vectors to show the strength (magnitude) and direction of the wind.\nVectors used in atmospheric science are often three-dimensional. We won’t cover three-dimensional motion in this text, but to go from two-dimensions to three-dimensions, you simply add a third vector component. Three-dimensional motion is represented as a combination of x -, y - and z components, where z is the altitude.\nVector calculus combines vector math with calculus, and is often used to find the rates of change in temperature, pressure or wind speed over time or distance. This is useful information, since atmospheric motion is driven by changes in pressure or temperature. The greater the variation in pressure over a given distance, the stronger the wind to try to correct that imbalance. Cold air tends to be more dense and therefore has higher pressure than warm air. Higher pressure air rushes into a region of lower pressure and gets deflected by the spinning of the Earth, and friction slows the wind at Earth’s surface.\nFinding how wind changes over distance and multiplying vectors lets meteorologists, like the one shown in [Figure 5.2], figure out how much rotation (spin) there is in the atmosphere at any given time and location. This is an important tool for tornado prediction. Conditions with greater rotation are more likely to produce tornadoes.","images":[{"sourceId":"fs-id1167066983691","filename":"CNX_HSPhysics_05_02_weather.jpg","relativePath":"media/CNX_HSPhysics_05_02_weather.jpg","alt":"A black and white photograph of a meteorologist is shown. The meteorologist is standing in front of a weather map with a television camera pointing at him."}]}],"summaryPoints":["The analytical method of vector addition and subtraction uses the Pythagorean theorem and trigonometric identities to determine the magnitude and direction of a resultant vector.","The steps to add vectors A and B using the analytical method are as follows:\nDetermine the coordinate system for the vectors. Then, determine the horizontal and vertical components of each vector using the equations\n\\({A}_{x} = A\\text{cos}\\theta {B}_{x} = B\\text{cos}\\theta\\)\nand\n\\({A}_{y} = A\\text{sin}\\theta {B}_{y} = B\\text{sin}\\theta \\text{.}\\)","Add the horizontal and vertical components of each vector to determine the components \\({R}_{x}\\) and \\({R}_{y}\\) of the resultant vector, R.\n\\({R}_{x} = {A}_{x} + {B}_{x}\\)\nand\n\\({R}_{y} = {A}_{y} + {B}_{y}.\\)","Use the Pythagorean theorem to determine the magnitude, \\(R\\), of the resultant vector R.\n\\(R = \\sqrt{{R}_{x}^{2} + {R}_{y}^{2}}\\)","Use a trigonometric identity to determine the direction, \\(\\theta\\), of R.\n\\(\\theta = {\\text{tan}}^{- 1}({R}_{y}/{R}_{x})\\)"],"glossary":[{"term":"analytical method","termVi":"Phương pháp giải tích (chiếu tọa độ)","definition":"the method of determining the magnitude and direction of a resultant vector using the Pythagorean theorem and trigonometric identities","definitionVi":"Chiếu các vectơ lên 2 trục vuông góc Ox, Oy bằng sin/cos rồi cộng đại số.","memoryTipVi":"Chính xác hơn nhiều so với vẽ hình."},{"term":"component (of a 2-dimensional vector)","termVi":"Thành phần vectơ (A_x, A_y)","definition":"a piece of a vector that points in a particular direction, usually in the direction of one of the axes of a chosen coordinate system; every 2-d vector can be expressed as a sum of two perpendicular vector components","definitionVi":"Hình chiếu của vectơ lên trục ngang x (A·cosθ) và trục đứng y (A·sinθ).","memoryTipVi":"A_x = A cosθ, A_y = A sinθ."}],"assessments":[{"uid":"hsphys.ch05.sec02.q001","sourceId":"fs-id1167064953118","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Between the analytical and graphical methods of vector additions, which is more accurate? Why?","images":[],"choices":[{"label":"a","text":"The analytical method is less accurate than the graphical method, because the former involves geometry and trigonometry."},{"label":"b","text":"The analytical method is more accurate than the graphical method, because the latter involves some extensive calculations."},{"label":"c","text":"The analytical method is less accurate than the graphical method, because the former includes drawing all figures to the right scale."},{"label":"d","text":"The analytical method is more accurate than the graphical method, because the latter is limited by the precision of the drawing."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q002","sourceId":"fs-id1167064746728","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What is a component of a two dimensional vector?","images":[],"choices":[{"label":"a","text":"A component is a piece of a vector that points in either the x or y direction."},{"label":"b","text":"A component is a piece of a vector that has half of the magnitude of the original vector."},{"label":"c","text":"A component is a piece of a vector that points in the direction opposite to the original vector."},{"label":"d","text":"A component is a piece of a vector that points in the same direction as original vector but with double of its magnitude."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q004","sourceId":"fs-id1167065944348","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"How can we determine the magnitude of a vector if we know the magnitudes of its components?","images":[],"choices":[{"label":"a","text":"\\(|\\vec{\\text{A}}| = {A}_{x} + {A}_{y}\\)"},{"label":"b","text":"\\(|\\vec{\\text{A}}| = {{A}_{x}}^{2} + {{A}_{y}}^{2}\\)"},{"label":"c","text":"\\(|\\vec{\\text{A}}| = \\sqrt{{{A}_{x}}^{2} + {{A}_{y}}^{2}}\\)"},{"label":"d","text":"\\(|\\vec{\\text{A}}| = ({{A}_{x}}^{2} + {{A}_{y}}^{2}{)}^{2}\\)"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q005","sourceId":"fs-id1167067105802","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the magnitude of a vector whose x -component is 4 cm and whose y -component is 3 cm?","images":[],"choices":[{"label":"a","text":"1 cm"},{"label":"b","text":"5 cm"},{"label":"c","text":"7 cm"},{"label":"d","text":"25 cm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q006","sourceId":"fs-id1167066983654","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the magnitude of a vector that makes an angle of 30° to the horizontal and whose x -component is 3 units?","images":[],"choices":[{"label":"a","text":"2.61 units"},{"label":"b","text":"3.00 units"},{"label":"c","text":"3.46 units"},{"label":"d","text":"6.00 units"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q010","sourceId":"eip-id1166849334084","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"True or FalseEvery 2-D vector can be expressed as the product of its x and y-components.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q013","sourceId":"fs-id1167067105802","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the magnitude of a vector whose x -component is 4 cm and whose y -component is 3 cm?","images":[],"choices":[{"label":"a","text":"1 cm"},{"label":"b","text":"5 cm"},{"label":"c","text":"7 cm"},{"label":"d","text":"25 cm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q014","sourceId":"fs-id1167066983654","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the magnitude of a vector that makes an angle of 30° to the horizontal and whose x -component is 3 units?","images":[],"choices":[{"label":"a","text":"2.61 units"},{"label":"b","text":"3.00 units"},{"label":"c","text":"3.46 units"},{"label":"d","text":"6.00 units"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q015","sourceId":"fs-id1167067095493","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A person walks 10.0 m north and then 2.00 m east. Solving analytically, what is the resultant displacement of the person?","images":[],"choices":[{"label":"a","text":"\\(\\vec{\\text{R}}\\) = 10.2 m, θ = 78.7º east of north"},{"label":"b","text":"\\(\\vec{\\text{R}}\\) = 10.2 m, θ = 78.7º north of east"},{"label":"c","text":"\\(\\vec{\\text{R}}\\) = 12.0 m, θ = 78.7º east of north"},{"label":"d","text":"\\(\\vec{\\text{R}}\\) = 12.0 m, θ = 78.7º north of east"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q019","sourceId":"fs-id1167067095592","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the dimensionality of vectors used in the study of atmospheric sciences?","images":[],"choices":[{"label":"a","text":"One-dimensional"},{"label":"b","text":"Two-dimensional"},{"label":"c","text":"Three-dimensional"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q020","sourceId":"fs-id1167067095612","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or False—A vector can form the shape of a right angle triangle with its x and y components.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q021","sourceId":"fs-id1167067095624","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or False—All vectors have positive x and y components.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q024","sourceId":"fs-id1167067086930","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"When a three dimensional vector is used in the study of atmospheric sciences, what is z?","images":[],"choices":[{"label":"a","text":"Altitude"},{"label":"b","text":"Heat"},{"label":"c","text":"Temperature"},{"label":"d","text":"Wind speed"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q025","sourceId":"fs-id1167067086941","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Which method is not an application of vector calculus?","images":[],"choices":[{"label":"a","text":"To find the rate of change in atmospheric temperature"},{"label":"b","text":"To study changes in wind speed and direction"},{"label":"c","text":"To predict changes in atmospheric pressure"},{"label":"d","text":"To measure changes in average rainfall"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q027","sourceId":"fs-id1167067086972","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"True or False—If only the angles of two vectors are known, we can find the angle of their resultant addition vector.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec02.q028","sourceId":"fs-id1167067086984","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"True or false—We can find the magnitude and direction of the resultant vector if we know the angles of two vectors and the magnitude of one.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":3,"keyEquationCount":5,"subsectionCount":3,"workedExampleCount":1,"snapLabCount":0,"glossaryCount":2,"assessmentCount":16}},{"uid":"hsphys.ch05.sec03","moduleId":"m54162","number":"5.3","slug":"projectile-motion","title":"Projectile Motion","isIntroduction":false,"learningObjectives":["Describe the properties of projectile motion","Apply kinematic equations and vectors to solve problems involving projectile motion"],"bilingualGuide":{"notebookSummaryVi":"Chuyển động ném ngang & ném xiên (Projectile Motion): tách thành 2 chuyển động độc lập — phương ngang thẳng đều (a_x = 0), phương đứng biến đổi đều (a_y = -g).","wordProblemCues":[{"phraseEn":"maximum height / range","meaningVi":"Độ cao cực đại (v_y = 0) / Tầm xa ngang","mathNotation":"H_max, R"}],"commonTrapsVi":["Tại điểm cao nhất, v_y = 0 nhưng gia tốc trọng trường vẫn là g = -9.8 m/s² (KHÔNG bằng 0!)."]},"keyEquations":[{"name":"angle of displacement","formula":"\\(\\theta = {tan}^{- 1}(\\mathbf{y}/\\mathbf{x})\\)"},{"name":"velocity","formula":"\\(\\mathbf{v} = \\sqrt{{\\mathbf{v}}_{x}^{2} + {\\mathbf{v}}_{y}^{2}}\\)"},{"name":"angle of velocity","formula":"\\({\\theta}_{v} = {tan}^{- 1}({\\mathbf{v}}_{y}/{\\mathbf{v}}_{x})\\)"},{"name":"maximum height","formula":"\\(h = \\frac{{\\mathbf{v}}_{0y}^{2}}{2\\mathbf{g}}\\)"},{"name":"range","formula":"\\(R = \\frac{{\\mathbf{v}}_{0}^{2}sin2{\\theta}_{0}}{\\mathbf{g}}\\)"}],"subsections":[{"uid":"hsphys.ch05.sec03.sub01","title":"Properties of Projectile Motion","summaryVi":null,"paragraphs":["Projectile motion is the motion of an object thrown (projected) into the air when, after the initial force that launches the object, air resistance is negligible and the only other force that object experiences is the force of gravity. The object is called a projectile , and its path is called its trajectory . Air resistance is a frictional force that slows its motion and can significantly alter the trajectory of the motion. Due to the difficulty in calculation, only situations in which the deviation from projectile motion is negligible and air resistance can be ignored are considered in introductory physics. That approximation is often quite accurate.","The most important concept in projectile motion is that when air resistance is ignored, horizontal and vertical motions are independent , meaning that they don’t influence one another. [Figure 5.3] compares a cannonball in free fall (in blue) to a cannonball launched horizontally in projectile motion (in red). You can see that the cannonball in free fall falls at the same rate as the cannonball in projectile motion. Keep in mind that if the cannon launched the ball with any vertical component to the velocity, the vertical displacements would not line up perfectly.","Since vertical and horizontal motions are independent, we can analyze them separately, along perpendicular axes. To do this, we separate projectile motion into the two components of its motion, one along the horizontal axis and the other along the vertical.","We’ll call the horizontal axis the x -axis and the vertical axis the y -axis. For notation, d is the total displacement, and x and y are its components along the horizontal and vertical axes. The magnitudes of these vectors are x and y , as illustrated in [Figure 5.3].","As usual, we use velocity, acceleration, and displacement to describe motion. We must also find the components of these variables along the x - and y -axes. The components of acceleration are then very simple a y = – g = –9.80 m/s 2 . Note that this definition defines the upwards direction as positive. Because gravity is vertical, a x = 0. Both accelerations are constant, so we can use the kinematic equations. For review, the kinematic equations from a previous chapter are summarized in [Table_05_01].","Where x is position, x 0 is initial position, v is velocity, v avg is average velocity, t is time and a is acceleration."],"figures":[{"sourceId":"fs-id1167066805388","filename":"CNX_HSPhysics_05_03_cannonball.jpg","relativePath":"media/CNX_HSPhysics_05_03_cannonball.jpg","alt":"A cannonball is sitting on a flat surface. Dotted lines show the projectile motion of a cannon ball. Dotted line A shows the ball dropping vertically. Dotted line B shows a curved path. Dotted line C shows the ball moving horizontally."},{"sourceId":"fs-id1167066855530","filename":"CNX_HSPhysics_05_03_soccer.jpg","relativePath":"media/CNX_HSPhysics_05_03_soccer.jpg","alt":"A boy is kicking a soccer ball. A curved line shows the ball's motion. A right triangle is drawn with vectors using an x-y axis. The hypotenuse is labeled d, the vertical leg is labeled y and the horizontal leg is labeled x."}],"tables":[{"sourceId":"Table_05_01","headers":[],"rows":[["\\(\\mathbf{x} = {\\mathbf{x}}_{0} + {\\mathbf{v}}_{\\mathbf{a}\\mathbf{v}\\mathbf{g}}t\\) (when \\(\\mathbf{a}\\text{=}\\text{constant}\\) )"],["\\({\\mathbf{v}}_{\\mathbf{a}\\mathbf{v}\\mathbf{g}} = \\frac{{\\mathbf{v}}_{0} + \\mathbf{v}}{2}\\) (when \\(\\mathbf{a}\\text{=}0\\) )"],["\\(\\mathbf{v} = {\\mathbf{v}}_{0} + \\mathbf{a}t\\)"],["\\(\\mathbf{x} = {\\mathbf{x}}_{0} + {\\mathbf{v}}_{0}t + \\frac{1}{2}\\mathbf{a}{t}^{2}\\)"],["\\({\\mathbf{v}}^{2} = {\\mathbf{v}}_{0}^{2} + 2\\mathbf{a}(\\mathbf{x} - {\\mathbf{x}}_{0})\\)"]]}]},{"uid":"hsphys.ch05.sec03.sub02","title":"Solve Problems Involving Projectile Motion","summaryVi":null,"paragraphs":["The following steps are used to analyze projectile motion:","The expression we found for \\(\\mathbf{y}\\) while solving part (a) of the previous problem works for any projectile motion problem where air resistance is negligible. Call the maximum height \\(\\mathbf{y} = h\\); then,","This equation defines the maximum height of a projectile . The maximum height depends only on the vertical component of the initial velocity."],"figures":[{"sourceId":"fs-id1167067042612","filename":"CNX_HSPhysics_05_03_projectile.jpg","relativePath":"media/CNX_HSPhysics_05_03_projectile.jpg","alt":"Four related diagrams of projectile motion are show, a, b, c, and d. Diagram a shows two-dimensional curved motion, vx and vy, along an x-y axis and includes the formulas V y equals negative V oy and angle equals negative angle o. Diagram b shows horizontal motion, vx. Diagram c shows upward and downward vertical velocity, vy. And diagram d shows the combination of vx, vy, and v, forming a right triangle."}],"tables":[]},{"uid":"hsphys.ch05.sec03.sub03","title":"Projectile Motion","summaryVi":null,"paragraphs":["The fact that vertical and horizontal motions are independent of each other lets us predict the range of a projectile. The range is the horizontal distance R traveled by a projectile on level ground, as illustrated in [Figure 5.3]. Throughout history, people have been interested in finding the range of projectiles for practical purposes, such as aiming cannons.","How does the initial velocity of a projectile affect its range? Obviously, the greater the initial speed \\({v}_{0}\\), the greater the range, as shown in the figure above. The initial angle \\({\\theta}_{0}\\) also has a dramatic effect on the range. When air resistance is negligible, the range \\(R\\) of a projectile on level ground is","where \\({v}_{0}\\) is the initial speed and \\({\\theta}_{0}\\) is the initial angle relative to the horizontal. It is important to note that the range doesn’t apply to problems where the initial and final y position are different, or to cases where the object is launched perfectly horizontally.","In this simulation you will learn about projectile motion by blasting objects out of a cannon. You can choose between objects such as a tank shell, a golf ball or even a Buick. Experiment with changing the angle, initial speed, and mass, and adding in air resistance. Make a game out of this simulation by trying to hit the target."],"figures":[{"sourceId":"fs-id1167067197490","filename":"CNX_HSPhysics_05_03_trajectory.jpg","relativePath":"media/CNX_HSPhysics_05_03_trajectory.jpg","alt":"Two trajectory diagrams are shown. Diagram a shows three trajectories that curve upward then downward. They are labeled as follows: thirty meters per second and ninety-eight point one meters; forty meters per second and one hundred sixty-three meters; fifty meters per second and two hundred fifty-five meters. Diagram b shows three trajectories that curve upward then downward. They are labeled as follows: fifteen degrees and one hundred twenty-eight meters; forty-five degrees and two hundred fifty-five meters; seventy-five degrees and one hundred twenty-eight meters. The diagram also includes the formula v o equals fifty meters per second."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch05.sec03.ex01","number":"5.3.1","title":"A Fireworks Projectile Explodes High and Away","problem":"During a fireworks display like the one illustrated in [Figure 5.3], a shell is shot into the air with an initial speed of 70.0 m/s at an angle of 75° above the horizontal. The fuse is timed to ignite the shell just as it reaches its highest point above the ground. (a) Calculate the height at which the shell explodes. (b) How much time passed between the launch of the shell and the explosion? (c) What is the horizontal displacement of the shell when it explodes?\nThe diagram shows the trajectory of a fireworks shell.","problemImages":[{"sourceId":"fs-id1167066787382","filename":"CNX_HSPhysics_05_03_firework.jpg","relativePath":"media/CNX_HSPhysics_05_03_firework.jpg","alt":"The diagram shows the trajectory of a fireworks shell. An x-axis is labeled x, a y-axis is labeled h, and a vector, labeled V o, points upward from the axis origin. An angle is formed by the vector and the x-axis with a measure of seventy-five degrees."}],"strategy":"The motion can be broken into horizontal and vertical motions in which \\({\\mathbf{a}}_{x} = 0\\) and \\({\\mathbf{a}}_{y} = \\mathbf{g}\\) . We can then define \\({\\mathbf{x}}_{0}\\) and \\({\\mathbf{y}}_{0}\\) to be zero and solve for the maximum height .","solution":"Solution for (a)\nBy height we mean the altitude or vertical position \\(\\mathbf{y}\\) above the starting point. The highest point in any trajectory, the maximum height, is reached when \\({\\mathbf{v}}_{y} = 0\\); this is the moment when the vertical velocity switches from positive (upwards) to negative (downwards). Since we know the initial velocity, initial position, and the value of v y when the firework reaches its maximum height, we use the following equation to find \\(\\mathbf{y}\\)\n\\({\\mathbf{v}}_{y}^{2} = {\\mathbf{v}}_{0y}^{2} - 2\\mathbf{g}(\\mathbf{y} - {y}_{0}).\\)\nBecause \\({\\mathbf{y}}_{0}\\) and \\({\\mathbf{v}}_{y}\\) are both zero, the equation simplifies to\n\\(0 = {\\mathbf{v}}_{0y}^{2} - 2\\mathbf{g}\\mathbf{y}.\\)\nSolving for \\(\\mathbf{y}\\) gives\n\\(\\mathbf{y} = \\frac{{\\mathbf{v}}_{0y}^{2}}{2\\mathbf{g}}.\\)\nNow we must find \\({\\mathbf{v}}_{\\text{0}y}\\), the component of the initial velocity in the y -direction. It is given by \\({\\mathbf{v}}_{0y} = {\\mathbf{v}}_{0}sin\\theta\\), where \\({\\mathbf{v}}_{0}\\) is the initial velocity of 70.0 m/s, and \\(\\theta = {75}^{∘}\\) is the initial angle. Thus,\n\\({\\mathbf{v}}_{0y} = {\\mathbf{v}}_{0}sin{\\theta}_{0} = (70.0\\,\\text{m/s})(sin{75}^{∘}) = 67.6\\,\\text{m/s}\\)\nand \\(\\mathbf{y}\\) is\n\\(\\mathbf{y} = \\frac{{(67.6\\,\\text{m/s})}^{2}}{2(9.80{\\text{m/s}}^{2}),}\\)\nso that\n\\(\\mathbf{y} = 233\\,\\text{m}\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"Since up is positive, the initial velocity and maximum height are positive, but the acceleration due to gravity is negative. The maximum height depends only on the vertical component of the initial velocity. The numbers in this example are reasonable for large fireworks displays, the shells of which do reach such heights before exploding."},{"uid":"hsphys.ch05.sec03.ex02","number":"5.3.2","title":"Calculating Projectile Motion: Hot Rock Projectile","problem":"Suppose a large rock is ejected from a volcano, as illustrated in [Figure 5.3], with a speed of \\(25.0\\text{m}/\\text{s}\\) and at an angle \\(35°\\) above the horizontal. The rock strikes the side of the volcano at an altitude 20.0 m lower than its starting point. (a) Calculate the time it takes the rock to follow this path.\nThe diagram shows the projectile motion of a large rock from a volcano.","problemImages":[{"sourceId":"fs-id1167066966587","filename":"CNX_HSPhysics_05_03_volcanic.jpg","relativePath":"media/CNX_HSPhysics_05_03_volcanic.jpg","alt":"A volcano is shown with labels illustrating the projectile motion of rock shooting out of the volcano. Vector v o equals twenty-five meters per second and points from the volcano opening upward. Vector v curves downward to the ground and forms an angle of thirty-five degrees with a horizontal plane at the height of the volcano opening. The distance between the horizontal plane and the ground is labeled as negative twenty meters."}],"strategy":"Breaking this two-dimensional motion into two independent one-dimensional motions will allow us to solve for the time. The time a projectile is in the air depends only on its vertical motion.","solution":"While the rock is in the air, it rises and then falls to a final position 20.0 m lower than its starting altitude. We can find the time for this by using\n\\(\\mathbf{y} = {\\mathbf{y}}_{0} + {\\mathbf{v}}_{0\\mathbf{y}}t - \\frac{1}{2}\\mathbf{g}{t}^{2}\\text{.}\\)\nIf we take the initial position \\({\\mathbf{y}}_{\\text{0}}\\) to be zero, then the final position is \\(\\mathbf{y} = - 20.0\\,\\text{m}\\text{.}\\) Now the initial vertical velocity is the vertical component of the initial velocity, found from\n\\({\\mathbf{v}}_{0}{}_{y} = {\\mathbf{v}}_{0}\\text{sin}{\\theta}_{0} = (25.0\\,\\text{m/s})(\\text{sin}{35}^{∘}) = 14.3\\,\\text{m/s}.\\)\nSubstituting known values yields\n\\(- 20.0\\,\\text{m} = (14.3\\,\\text{m/s)}t - (4.90{\\text{m/s}}^{2}){t}^{2}\\text{.}\\)\nRearranging terms gives a quadratic equation in \\(t\\)\n\\((4.90{\\text{m/s}}^{2}){t}^{2} - (\\text{14}\\text{.3 m/s})t - (20.0\\,\\text{m}) = 0\\text{.}\\)\nThis expression is a quadratic equation of the form \\(a{t}^{2} + bt + c = 0\\), where the constants are a = 4.90, b = –14.3, and c = –20.0. Its solutions are given by the quadratic formula\n\\(t = \\frac{- b \\pm \\sqrt{{b}^{2} - 4ac}}{2a}\\text{.}\\)\nThis equation yields two solutions t = 3.96 and t = –1.03. You may verify these solutions as an exercise. The time is t = 3.96 s or –1.03 s. The negative value of time implies an event before the start of motion, so we discard it. Therefore,\n\\(t = 3.96\\,\\text{s.}\\)","solutionImages":[],"solutionTables":[],"discussion":"The time for projectile motion is completely determined by the vertical motion. So any projectile that has an initial vertical velocity of \\(14.3\\text{m}/\\text{s}\\) and lands 20.0 m below its starting altitude will spend 3.96 s in the air."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch05.sec03.feat01","type":"tip","title":"Tips for Success","text":"For problems of projectile motion, it is important to set up a coordinate system. The first step is to choose an initial position for \\(\\mathbf{x}\\) and \\(\\mathbf{y}\\) . Usually, it is simplest to set the initial position of the object so that \\({\\mathbf{x}}_{0} = 0\\) and \\({\\mathbf{y}}_{0} = 0\\) .","images":[]}],"summaryPoints":["Projectile motion is the motion of an object through the air that is subject only to the acceleration of gravity.","Projectile motion in the horizontal and vertical directions are independent of one another.","The maximum height of an projectile is the highest altitude, or maximum displacement in the vertical position reached in the path of a projectile.","The range is the maximum horizontal distance traveled by a projectile.","To solve projectile problems: choose a coordinate system; analyze the motion in the vertical and horizontal direction separately; then, recombine the horizontal and vertical components using vector addition equations."],"glossary":[{"term":"air resistance","termVi":"Lực cản không khí","definition":"a frictional force that slows the motion of objects as they travel through the air; when solving basic physics problems, air resistance is assumed to be zero","definitionVi":"Lực ma sát của không khí cản trở vật chuyển động qua nó.","memoryTipVi":"Trong bài toán ném xiên lý tưởng, thường giả sử bỏ qua lực cản không khí (negligible)."},{"term":"maximum height (of a projectile)","termVi":"Độ cao cực đại (H_max)","definition":"the highest altitude, or maximum displacement in the vertical position reached in the path of a projectile","definitionVi":"Độ cao lớn nhất vật ném đạt được (tại đó vận tốc theo phương đứng v_y = 0).","memoryTipVi":"Tại đỉnh quỹ đạo: v_y = 0, nhưng v_x vẫn ≠ 0!"},{"term":"projectile","termVi":"Vật ném (Vật chuyển động ném)","definition":"an object that travels through the air and experiences only acceleration due to gravity","definitionVi":"Vật được ném vào không trung và sau đó chỉ chịu tác dụng của trọng lực.","memoryTipVi":"Quỹ đạo là một đường Parabol."},{"term":"projectile motion","termVi":"Chuyển động ném ngang / ném xiên","definition":"the motion of an object that is subject only to the acceleration of gravity","definitionVi":"Chuyển động 2 chiều gồm phương ngang đều (a_x = 0) và phương đứng rơi tự do (a_y = -g) hoàn toàn độc lập nhau.","memoryTipVi":"Chìa khóa giải bài: tách riêng Ox và Oy!"},{"term":"range","termVi":"Tầm bay xa (R)","definition":"the maximum horizontal distance that a projectile travels","definitionVi":"Khoảng cách theo phương ngang vật ném đi được cho tới khi chạm đất.","memoryTipVi":"Góc ném 45° cho tầm xa lớn nhất (khi bỏ qua sức cản không khí)."},{"term":"trajectory","termVi":"Quỹ đạo chuyển động","definition":"the path of a projectile through the air","definitionVi":"Đường cong vạch ra trong không gian bởi vật chuyển động.","memoryTipVi":"Quỹ đạo ném xiên là Parabol."}],"assessments":[{"uid":"hsphys.ch05.sec03.q002","sourceId":"fs-id1167067154414","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What is the force experienced by a projectile after the initial force that launched it into the air in the absence of air resistance?","images":[],"choices":[{"label":"a","text":"The nuclear force"},{"label":"b","text":"The gravitational force"},{"label":"c","text":"The electromagnetic force"},{"label":"d","text":"The contact force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec03.q008","sourceId":"eip-id1166849870638","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"An object is launched into the air. If the y-component of its acceleration is 9.8 m/s 2 , which direction is defined as positive?","images":[],"choices":[{"label":"a","text":"Vertically upward in the coordinate system"},{"label":"b","text":"Vertically downward in the coordinate system"},{"label":"c","text":"Horizontally to the right side of the coordinate system"},{"label":"d","text":"Horizontally to the left side of the coordinate system"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec03.q012","sourceId":"fs-id1167067217787","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A person wants to fire a water balloon cannon such that it hits a target 100 m away. If the cannon can only be launched at 45° above the horizontal, what should be the initial speed at which it is launched?","images":[],"choices":[{"label":"a","text":"31.3 m/s"},{"label":"b","text":"37.2 m/s"},{"label":"c","text":"980.0 m/s"},{"label":"d","text":"1,385.9 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec03.q013","sourceId":"fs-id1167067041208","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"After a projectile is launched in the air, in which direction does it experience constant, non-zero acceleration, ignoring air resistance?","images":[],"choices":[{"label":"a","text":"The x direction"},{"label":"b","text":"The y direction"},{"label":"c","text":"Both the x and y directions"},{"label":"d","text":"Neither direction"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec03.q015","sourceId":"eip-id1166849352358","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A ball is thrown in the air at an angle of 40°. If the maximum height it reaches is 10 m, what must be its initial speed?","images":[],"choices":[{"label":"a","text":"17.46 m/s"},{"label":"b","text":"21.78 m/s"},{"label":"c","text":"304.92 m/s"},{"label":"d","text":"474.37 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec03.q018","sourceId":"fs-id1167067078060","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"In the equation for the maximum height of a projectile, what does \\({v}_{0y}\\) stand for?\n\\(h = \\frac{{v}_{0y}{}^{2}}{2g}\\)","images":[],"choices":[{"label":"a","text":"Initial velocity in the x direction"},{"label":"b","text":"Initial velocity in the y direction"},{"label":"c","text":"Final velocity in the x direction"},{"label":"d","text":"Final velocity in the y direction"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec03.q019","sourceId":"fs-id1167067139230","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or False—Range is defined as the maximum vertical distance travelled by a projectile.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":5,"subsectionCount":3,"workedExampleCount":2,"snapLabCount":0,"glossaryCount":6,"assessmentCount":7}},{"uid":"hsphys.ch05.sec04","moduleId":"m54159","number":"5.4","slug":"inclined-planes","title":"Inclined Planes","isIntroduction":false,"learningObjectives":["Distinguish between static friction and kinetic friction","Solve problems involving inclined planes"],"bilingualGuide":{"notebookSummaryVi":"Bài toán Mặt phẳng nghiêng (Inclined Planes) và Ma sát nghỉ / Ma sát trượt (f_k = μ_k N).","wordProblemCues":[{"phraseEn":"parallel / perpendicular to incline","meaningVi":"Song song mặt nghiêng (mg sinθ) / Vuông góc (mg cosθ)","mathNotation":"N = mg cosθ"}],"commonTrapsVi":["Trên mặt phẳng nghiêng góc θ, phản lực N = mg cosθ (NHỎ HƠN mg), KHÔNG bằng mg!"]},"keyEquations":[{"name":"force of static friction","formula":"\\({\\mathbf{f}}_{\\text{s}} \\le {\\mu}_{\\text{s}}\\mathbf{N}\\)"},{"name":"force of kinetic friction","formula":"\\({\\mathbf{f}}_{\\text{k}} = {\\mu}_{\\text{k}}\\mathbf{N}\\)"},{"name":"perpendicular component of weight on an inclined plane","formula":"\\({\\mathbf{w}}_{⊥} = \\mathbf{w}\\text{cos}(\\theta ) = m\\mathbf{g}\\text{cos}(\\theta )\\)"},{"name":"parallel component of weight on an inclined plane","formula":"\\({\\mathbf{w}}_{||} = \\mathbf{w}\\text{sin}(\\theta ) = m\\mathbf{g}\\text{sin}(\\theta )\\)"}],"subsections":[{"uid":"hsphys.ch05.sec04.sub01","title":"Static Friction and Kinetic Friction","summaryVi":null,"paragraphs":["Recall from the previous chapter that friction is a force that opposes relative motion parallel to the contact surface of the interacting objects and is around us all the time. Friction allows us to move, which you have discovered if you have ever tried to walk on ice.","There are different types of friction—kinetic and static. Kinetic friction acts on an object in relative motion, while static friction acts on an object or system at rest relative to each other. The maximum static friction is usually greater than the kinetic friction between the objects.","Imagine, for example, trying to slide a heavy crate across a concrete floor. You may push harder and harder on the crate and not move it at all. This means that the static friction responds to what you do—it increases to be equal to and in the opposite direction of your push. But if you finally push hard enough, the crate seems to slip suddenly and starts to move. Once in motion, it is easier to keep it in motion than it was to get it started because the kinetic friction force is less than the static friction force. If you were to add mass to the crate, (for example, by placing a box on top of it) you would need to push even harder to get it started and also to keep it moving. If, on the other hand, you oiled the concrete you would find it easier to get the crate started and keep it going.","[Figure 5.4] shows how friction occurs at the interface between two objects. Magnifying these surfaces shows that they are rough on the microscopic level. So when you push to get an object moving (in this case, a crate), you must raise the object until it can skip along with just the tips of the surface hitting, break off the points, or do both. The harder the surfaces are pushed together (such as if another box is placed on the crate), the more force is needed to move them.","The magnitude of the frictional force has two forms: one for static friction, the other for kinetic friction. When there is no motion between the objects, the magnitude of static friction f s is","where \\({\\mu}_{\\text{s}}\\) is the coefficient of static friction and N is the magnitude of the normal force. Recall that the normal force acts perpendicular to the surface and prevents the crate from falling through the floor. It opposes the force of gravity in this example, but that will not always be the case.","Since the symbol \\(\\le\\) means less than or equal to, this equation says that static friction can have a maximum value of \\({\\mu}_{\\text{s}}\\mathbf{N}.\\) That is,","Static friction is a responsive force that increases to be equal and opposite to whatever force is exerted, up to its maximum limit. Once the applied force exceeds f s(max), the object will move. Once an object is moving, the magnitude of kinetic friction f k is given by","where \\({\\mu}_{\\text{k}}\\) is the coefficient of kinetic friction.","Friction varies from surface to surface because different substances are rougher than others. [Table_05_02] compares values of static and kinetic friction for different surfaces. The coefficient of the friction depends on the two surfaces that are in contact.","Since friction always opposes relative motion, the direction of friction is upward along the plane if the object is at rest or sliding down the incline. For example, if the crate you try to push (with a force parallel to the floor) has a mass of 100 kg, then the normal force would be equal to its weight","perpendicular to the floor. If the coefficient of static friction is 0.45, you would have to exert a force parallel to the floor greater than","to move the crate. Once there is motion, friction is less and the coefficient of kinetic friction might be 0.30, so that a force of only 290 N","would keep it moving at a constant speed. If the floor were lubricated, both coefficients would be much smaller than they would be without lubrication. The coefficient of friction is unitless and is a number usually between 0 and 1.0, but there is no theoretical upper limit to its value."],"figures":[{"sourceId":"fs-id1167067023978","filename":"CNX_HSPhysics_05_04_surface.jpg","relativePath":"media/CNX_HSPhysics_05_04_surface.jpg","alt":"A box is shown sitting on a floor. A vector labeled f points to the left from the area where the bottom of the box meets the floor. A zoom-in diagram shows the bottom surface of the box and the surface of the floor as rough."}],"tables":[{"sourceId":"Table_05_02","headers":["System","Static Friction \\({\\mu}_{\\text{s}}\\)","Kinetic Friction \\({\\mu}_{\\text{k}}\\)"],"rows":[["Rubber on dry concrete","1.0","0.7"],["Rubber on wet concrete","0.7","0.5"],["Wood on wood","0.5","0.3"],["Waxed wood on wet snow","0.14","0.1"],["Metal on wood","0.5","0.3"],["Steel on steel (dry)","0.6","0.3"],["Steel on steel (oiled)","0.05","0.03"],["Teflon on steel","0.04","0.04"],["Bone lubricated by synovial fluid","0.016","0.015"],["Shoes on wood","0.9","0.7"],["Shoes on ice","0.1","0.05"],["Ice on ice","0.1","0.03"],["Steel on ice","0.4","0.02"]]}]},{"uid":"hsphys.ch05.sec04.sub02","title":"Working with Inclined Planes","summaryVi":null,"paragraphs":["We discussed previously that when an object rests on a horizontal surface, there is a normal force supporting it equal in magnitude to its weight. Up until now, we dealt only with normal force in one dimension, with gravity and normal force acting perpendicular to the surface in opposing directions (gravity downward, and normal force upward). Now that you have the skills to work with forces in two dimensions, we can explore what happens to weight and the normal force on a tilted surface such as an inclined plane. For inclined plane problems, it is easier breaking down the forces into their components if we rotate the coordinate system, as illustrated in [Figure 5.4]. The first step when setting up the problem is to break down the force of weight into components.","When an object rests on an incline that makes an angle \\(\\theta\\) with the horizontal, the force of gravity acting on the object is divided into two components: A force acting perpendicular to the plane, \\({\\mathbf{w}}_{⊥}\\), and a force acting parallel to the plane, \\({\\mathbf{w}}_{||}\\) . The perpendicular force of weight, \\({\\mathbf{w}}_{⊥}\\), is typically equal in magnitude and opposite in direction to the normal force, \\(\\mathbf{N}.\\) The force acting parallel to the plane, \\({\\mathbf{w}}_{||}\\), causes the object to accelerate down the incline. The force of friction, \\(\\mathbf{f}\\), opposes the motion of the object, so it acts upward along the plane.","It is important to be careful when resolving the weight of the object into components. If the angle of the incline is at an angle \\(\\theta\\) to the horizontal, then the magnitudes of the weight components are","Instead of memorizing these equations, it is helpful to be able to determine them from reason. To do this, draw the right triangle formed by the three weight vectors. Notice that the angle of the incline is the same as the angle formed between \\(\\mathbf{w}\\) and \\({\\mathbf{w}}_{⊥}\\) . Knowing this property, you can use trigonometry to determine the magnitude of the weight components","To review, the process for solving inclined plane problems is as follows:"],"figures":[{"sourceId":"fs-id1167066859356","filename":"CNX_HSPhysics_05_04_weight.jpg","relativePath":"media/CNX_HSPhysics_05_04_weight.jpg","alt":"A diagram shows perpendicular and horizontal components of weight. The weight is on an inclined plane that slopes downward to the right."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch05.sec04.ex01","number":"5.4.1","title":"Finding the Coefficient of Kinetic Friction on an Inclined Plane","problem":"A skier, illustrated in [Figure 5.4] (a) , with a mass of 62 kg is sliding down a snowy slope at an angle of 25 degrees. Find the coefficient of kinetic friction for the skier if friction is known to be 45.0 N.\nUse the diagram to help find the coefficient of kinetic friction for the skier.","problemImages":[{"sourceId":"fs-id1167066842678","filename":"CNX_HSPhysics_05_04_skier(a).jpg","relativePath":"media/CNX_HSPhysics_05_04_skier(a).jpg","alt":"A skier is moving down a slope with an angle measure of twenty-five degrees to the ground. Force vectors are shown: N points upward from the skier, f points to the right of the skis, w points at a downward left angle from the skiers' feet, forming an angle with vector w that has a measure of twenty-five degrees. A free-body diagram illustrates the right triangle formed by these vectors."}],"strategy":"The magnitude of kinetic friction was given as 45.0 N. Kinetic friction is related to the normal force N as \\({\\mathbf{f}}_{\\text{k}} = {\\mu}_{\\text{k}}\\mathbf{N}\\) . Therefore, we can find the coefficient of kinetic friction by first finding the normal force of the skier on a slope. The normal force is always perpendicular to the surface, and since there is no motion perpendicular to the surface, the normal force should equal the component of the skier’s weight perpendicular to the slope.\nThat is,\n\\(\\mathbf{N} = {\\mathbf{w}}_{⊥} = \\mathbf{w}\\text{cos}({25}^{∘}) = m\\mathbf{g}\\text{cos}({25}^{∘})\\text{.}\\)\nSubstituting this into our expression for kinetic friction, we get\n\\({\\mathbf{f}}_{\\text{k}} = {\\mu}_{\\text{k}}m\\mathbf{g}{\\text{cos 25}}^{∘},\\)\nwhich can now be solved for the coefficient of kinetic friction μ k .","solution":"Solving for \\({\\mu}_{\\text{k}}\\) gives\n\\({\\mu}_{\\text{k}} = \\frac{{\\mathbf{f}}_{\\text{k}}}{\\mathbf{w}{\\text{cos 25}}^{∘}} = \\frac{{\\mathbf{f}}_{\\text{k}}}{m\\mathbf{g}{\\text{cos 25}}^{∘}}\\text{.}\\)\nSubstituting known values on the right-hand side of the equation,\n\\({\\mu}_{\\text{k}} = \\frac{45.0\\,\\text{N}}{(62\\,\\text{kg)(9}{\\text{.80 m/s}}^{2})(0.906)} = 0.082\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"This result is a little smaller than the coefficient listed in [Table_05_02] for waxed wood on snow, but it is still reasonable since values of the coefficients of friction can vary greatly. In situations like this, where an object of mass m slides down a slope that makes an angle θ with the horizontal, friction is given by \\({\\mathbf{f}}_{\\text{k}} = {\\mu}_{\\text{k}}m\\mathbf{g}\\text{cos}\\theta .\\)"},{"uid":"hsphys.ch05.sec04.ex02","number":"5.4.2","title":"Weight on an Incline, a Two-Dimensional Problem","problem":"The skier’s mass, including equipment, is 60.0 kg. (See [Figure 5.4] (b) .) (a) What is her acceleration if friction is negligible? (b) What is her acceleration if the frictional force is 45.0 N?\nNow use the diagram to help find the skier's acceleration if friction is negligible and if the frictional force is 45.0 N.","problemImages":[{"sourceId":"fs-id1167066970776","filename":"CNX_HSPhysics_05_04_skier(b).jpg","relativePath":"media/CNX_HSPhysics_05_04_skier(b).jpg","alt":"A skier is moving down a slope with an angle measure of twenty-five degrees to the ground. Force vectors are shown: N points upward from the skier, f points to the right of the skis, w points at a downward left angle from the skiers' feet, forming an angle with vector w that has a measure of twenty-five degrees. A free-body diagram illustrates the right triangle formed by these vectors."}],"strategy":"The most convenient coordinate system for motion on an incline is one that has one coordinate parallel to the slope and one perpendicular to the slope. Remember that motions along perpendicular axes are independent. We use the symbol \\(⊥\\) to mean perpendicular, and \\(||\\) to mean parallel.\nThe only external forces acting on the system are the skier’s weight, friction, and the normal force exerted by the ski slope, labeled \\(\\mathbf{w}\\), \\(\\mathbf{f}\\), and \\(\\mathbf{N}\\) in the free-body diagram. \\(\\mathbf{N}\\) is always perpendicular to the slope and \\(\\mathbf{f}\\) is parallel to it. But \\(\\mathbf{w}\\) is not in the direction of either axis, so we must break it down into components along the chosen axes. We define \\({\\mathbf{w}}_{||}\\) to be the component of weight parallel to the slope and \\({\\mathbf{w}}_{⊥}\\) the component of weight perpendicular to the slope. Once this is done, we can consider the two separate problems of forces parallel to the slope and forces perpendicular to the slope.","solution":"The magnitude of the component of the weight parallel to the slope is \\({\\mathbf{w}}_{||} = \\mathbf{w}\\text{sin}(25°) = m\\mathbf{g}\\text{sin}(25°)\\), and the magnitude of the component of the weight perpendicular to the slope is \\({\\mathbf{w}}_{⊥} = \\mathbf{w}\\text{cos}(25°) = m\\mathbf{g}\\text{cos}(25°).\\)\n(a) Neglecting friction: Since the acceleration is parallel to the slope, we only need to consider forces parallel to the slope. Forces perpendicular to the slope add to zero, since there is no acceleration in that direction. The forces parallel to the slope are the amount of the skier’s weight parallel to the slope \\({\\mathbf{w}}_{||}\\) and friction \\(\\mathbf{f}\\) . Assuming no friction, by Newton’s second law the acceleration parallel to the slope is\n\\({\\mathbf{a}}_{||} = \\frac{{\\mathbf{F}}_{\\text{net ||}}}{m},\\)\nWhere the net force parallel to the slope \\({\\mathbf{F}}_{\\text{net ||}} = {\\mathbf{w}}_{||} = m\\mathbf{g}\\text{sin}(25°)\\), so that\n\\({\\mathbf{a}}_{||} = \\frac{{\\mathbf{F}}_{\\text{net ||}}}{m} = \\frac{m\\mathbf{g}\\text{sin}(25°)}{m} = \\mathbf{g}\\text{sin}(25°) = (9.80{\\text{m/s}}^{2})(0.423) = 4.14{\\text{m/s}}^{2}\\) is the acceleration.\n(b) Including friction: Here we now have a given value for friction, and we know its direction is parallel to the slope and it opposes motion between surfaces in contact. So the net external force is now\n\\({\\mathbf{F}}_{\\text{net}||} = {\\mathbf{w}}_{||} - \\mathbf{f},\\)\nand substituting this into Newton’s second law, \\({a}_{||} = \\frac{{\\mathbf{F}}_{\\text{net ||}}}{m}\\) gives\n\\({\\mathbf{a}}_{||} = \\frac{{\\mathbf{F}}_{\\text{net ||}}}{m} = \\frac{{\\mathbf{w}}_{||} - \\mathbf{f}}{m} = \\frac{m\\mathbf{g}\\text{sin}(25°) - \\mathbf{f}}{m}.\\) We substitute known values to get\n\\({\\mathbf{a}}_{||} = \\frac{\\text{(60}\\text{.0 kg)(9}{\\text{.80 m/s}}^{\\text{2}}\\text{)(0}\\text{.423)} - \\text{45}\\text{.0 N}}{\\text{60}\\text{.0 kg}},\\)\nor\n\\({\\mathbf{a}}_{||} = \\text{3}{\\text{.39 m/s}}^{\\text{2}},\\)\nwhich is the acceleration parallel to the incline when there is 45 N opposing friction.","solutionImages":[],"solutionTables":[],"discussion":"Since friction always opposes motion between surfaces, the acceleration is smaller when there is friction than when there is not."}],"snapLabs":[{"uid":"hsphys.ch05.sec04.lab01","title":"Friction at an Angle: Sliding a Coin","text":"An object will slide down an inclined plane at a constant velocity if the net force on the object is zero. We can use this fact to measure the coefficient of kinetic friction between two objects. As shown in the first Worked Example , the kinetic friction on a slope \\({\\mathbf{f}}_{\\text{k}} = {\\mu}_{\\text{k}}m\\mathbf{g}\\text{cos}\\theta\\), and the component of the weight down the slope is equal to \\(m\\mathbf{g}\\text{sin}\\theta\\) . These forces act in opposite directions, so when they have equal magnitude, the acceleration is zero. Writing these out\n\\({\\mathbf{f}}_{\\text{k}} = \\mathbf{F}{\\mathbf{g}}_{x}{\\mu}_{\\text{k}}m\\mathbf{g}\\text{cos}\\theta = m\\mathbf{g}\\text{sin}θ.\\)\nSolving for \\({\\mu}_{\\text{k}}\\), since \\(\\text{tan}\\theta = \\text{sin}\\theta \\text{/cos}\\theta\\) we find that\n\\({\\mu}_{\\text{k}} = \\frac{m\\mathbf{g}\\text{sin}\\theta}{m\\mathbf{g}\\text{cos}\\theta} = \\text{tan}θ.\\)\n1 coin\n1 book\n1 protractor\nPut a coin flat on a book and tilt it until the coin slides at a constant velocity down the book. You might need to tap the book lightly to get the coin to move.\nMeasure the angle of tilt relative to the horizontal and find \\({\\mu}_{\\text{k}}\\) .","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch05.sec04.feat01","type":"tip","title":"Tips for Success","text":"Normal force is represented by the variable \\(\\mathbf{N}.\\) This should not be confused with the symbol for the newton, which is also represented by the letter N. It is important to tell apart these symbols, especially since the units for normal force ( \\(\\mathbf{N}\\) ) happen to be newtons (N). For example, the normal force, \\(\\mathbf{N}\\), that the floor exerts on a chair might be \\(\\mathbf{N} = 100\\,\\text{N}\\text{.}\\) One important difference is that normal force is a vector, while the newton is simply a unit. Be careful not to confuse these letters in your calculations!","images":[]}],"summaryPoints":["Friction is a contact force between systems that opposes the motion or attempted motion between them. Simple friction is proportional to the normal force N pushing the systems together. A normal force is always perpendicular to the contact surface between systems. Friction depends on both of the materials involved.","µ s is the coefficient of static friction, which depends on both of the materials.","µ k is the coefficient of kinetic friction, which also depends on both materials.","When objects rest on an inclined plane that makes an angle \\(\\theta\\) with the horizontal surface, the weight of the object can be broken into components that act perpendicular \\(({\\mathbf{w}}_{⊥})\\)\nand parallel ( \\({\\mathbf{w}}_{||}\\) ) to the surface of the plane."],"glossary":[{"term":"kinetic friction","termVi":"Lực ma sát trượt (f_k)","definition":"a force that opposes the motion of two systems that are in contact and moving relative to one another","definitionVi":"Lực ma sát tác dụng khi vật ĐANG trượt trên bề mặt: f_k = μ_k · N.","memoryTipVi":"Kinetic = chuyển động → Ma sát trượt."},{"term":"static friction","termVi":"Lực ma sát nghỉ (f_s)","definition":"a force that prevents the relative motion of two systems that are in contact and are not moving relative to one another","definitionVi":"Lực ma sát giữ vật đứng yên chưa trượt: f_s ≤ μ_s · N.","memoryTipVi":"Hệ số ma sát nghỉ μ_s luôn lớn hơn ma sát trượt μ_k."}],"assessments":[{"uid":"hsphys.ch05.sec04.q004","sourceId":"fs-id1167066825236","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"When an object sits on an inclined plane that makes an angle θ with the horizontal, what is the expression for the component of the objects weight force that is parallel to the incline?","images":[],"choices":[{"label":"a","text":"\\({w}_{\\text{||}} = w\\text{cos}\\theta\\)"},{"label":"b","text":"\\({w}_{\\text{||}} = w\\text{sin}\\theta\\)"},{"label":"c","text":"\\({w}_{\\text{||}} = w\\text{sin}\\theta - \\text{cos}\\theta\\)"},{"label":"d","text":"\\({w}_{\\text{||}} = w\\text{cos}\\theta - \\text{sin}\\theta\\)"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec04.q006","sourceId":"fs-id1167067015184","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"True or FalseKinetic friction is less than the limiting static friction because once an object is moving, there are fewer points of contact, and the friction is reduced. For this reason, more force is needed to start moving an object than to keep it in motion.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec04.q011","sourceId":"fs-id1167066825236","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"When an object sits on an inclined plane that makes an angle θ with the horizontal, what is the expression for the component of the objects weight force that is parallel to the incline?","images":[],"choices":[{"label":"a","text":"\\({w}_{\\text{||}} = w\\text{cos}\\theta\\)"},{"label":"b","text":"\\({w}_{\\text{||}} = w\\text{sin}\\theta\\)"},{"label":"c","text":"\\({w}_{\\text{||}} = w\\text{sin}\\theta - \\text{cos}\\theta\\)"},{"label":"d","text":"\\({w}_{\\text{||}} = w\\text{cos}\\theta - \\text{sin}\\theta\\)"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec04.q014","sourceId":"fs-id1167067179222","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A skier with a mass of 55 kg is skiing down a snowy slope that has an incline of 30°. Find the coefficient of kinetic friction for the skier if friction is known to be 25 N .","images":[],"choices":[{"label":"a","text":"\\(\\mu k = 0\\)"},{"label":"b","text":"\\(\\mu k = 0.05\\)"},{"label":"c","text":"\\(\\mu k = 0.09\\)"},{"label":"d","text":"\\(\\mu k = ∞\\)"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec04.q015","sourceId":"fs-id1167067075011","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"For objects of identical masses but made of different materials, which of the following experiences the most static friction?","images":[],"choices":[{"label":"a","text":"Shoes on ice"},{"label":"b","text":"Metal on wood"},{"label":"c","text":"Teflon on steel"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec04.q016","sourceId":"fs-id1167066959478","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"If an object sits on an inclined plane and no other object makes contact with the object, what is typically equal in magnitude to the component of the weight perpendicular to the plane?","images":[],"choices":[{"label":"a","text":"The normal force"},{"label":"b","text":"The total weight"},{"label":"c","text":"The parallel force of weight"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec04.q017","sourceId":"eip-id1166849973741","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A 5 kg box is at rest on the floor. The coefficient of static friction between the box and the floor is 0.4. A horizontal force of 50 N is applied to the box. Will it move?","images":[],"choices":[{"label":"a","text":"No, because the applied force is less than the maximum limiting static friction."},{"label":"b","text":"No, because the applied force is more than the maximum limiting static friction."},{"label":"c","text":"Yes, because the applied force is less than the maximum limiting static friction."},{"label":"d","text":"Yes, because the applied force is more than the maximum limiting static friction."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec04.q018","sourceId":"eip-id1166849927556","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A skier with a mass of 67 kg is skiing down a snowy slope with an incline of 37°. Find the friction if the coefficient of kinetic friction is 0.07.","images":[],"choices":[{"label":"a","text":"27.66 N"},{"label":"b","text":"34.70 N"},{"label":"c","text":"36.71 N"},{"label":"d","text":"45.96 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec04.q023","sourceId":"fs-id1167066880642","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"True or False—Friction varies from surface to surface because different substances have different degrees of roughness or smoothness.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":4,"subsectionCount":2,"workedExampleCount":2,"snapLabCount":1,"glossaryCount":2,"assessmentCount":9}},{"uid":"hsphys.ch05.sec05","moduleId":"m54154","number":"5.5","slug":"simple-harmonic-motion","title":"Simple Harmonic Motion","isIntroduction":false,"learningObjectives":["Describe Hooke’s law and Simple Harmonic Motion","Describe periodic motion, oscillations, amplitude, frequency, and period","Solve problems in simple harmonic motion involving springs and pendulums"],"bilingualGuide":{"notebookSummaryVi":"Dao động điều hòa (SHM), Định luật Hooke (F = -kx), Chu kỳ (T), Tần số (f = 1/T) và Con lắc đơn (T = 2π√(L/g)).","wordProblemCues":[{"phraseEn":"period T / frequency f","meaningVi":"Chu kỳ (s) / Tần số (Hz)","mathNotation":"T = 1/f"}],"commonTrapsVi":["Chu kỳ con lắc đơn chỉ phụ thuộc chiều dài dây L và g, KHÔNG phụ thuộc khối lượng m!"]},"keyEquations":[{"name":"Hooke’s law","formula":"\\(\\mathbf{F} = - \\mathbf{k}\\mathbf{x}\\)"},{"name":"period in simple harmonic motion","formula":"\\(T = 2\\pi \\sqrt{\\frac{m}{\\mathbf{k}}}\\)"},{"name":"frequency in simple harmonic motion","formula":"\\(f = \\frac{1}{2\\pi}\\sqrt{\\frac{\\mathbf{k}}{m}}\\)"},{"name":"period of a simple pendulum","formula":"\\(T = 2\\pi \\sqrt{\\frac{L}{\\mathbf{g}}}\\)"}],"subsections":[{"uid":"hsphys.ch05.sec05.sub01","title":"Hooke’s Law and Simple Harmonic Motion","summaryVi":null,"paragraphs":["Imagine a car parked against a wall. If a bulldozer pushes the car into the wall, the car will not move but it will noticeably change shape. A change in shape due to the application of a force is a deformation . Even very small forces are known to cause some deformation. For small deformations, two important things can happen. First, unlike the car and bulldozer example, the object returns to its original shape when the force is removed. Second, the size of the deformation is proportional to the force. This second property is known as Hooke’s law . In equation form, Hooke’s law is","where x is the amount of deformation (the change in length, for example) produced by the restoring force F , and k is a constant that depends on the shape and composition of the object. The restoring force is the force that brings the object back to its equilibrium position; the minus sign is there because the restoring force acts in the direction opposite to the displacement. Note that the restoring force is proportional to the deformation x . The deformation can also be thought of as a displacement from equilibrium. It is a change in position due to a force. In the absence of force, the object would rest at its equilibrium position. The force constant k is related to the stiffness of a system. The larger the force constant, the stiffer the system. A stiffer system is more difficult to deform and requires a greater restoring force. The units of k are newtons per meter (N/m). One of the most common uses of Hooke’s law is solving problems involving springs and pendulums, which we will cover at the end of this section."],"figures":[],"tables":[]},{"uid":"hsphys.ch05.sec05.sub02","title":"Oscillations and Periodic Motion","summaryVi":null,"paragraphs":["What do an ocean buoy, a child in a swing, a guitar, and the beating of hearts all have in common? They all oscillate . That is, they move back and forth between two points, like the ruler illustrated in [Figure 5.5]. All oscillations involve force. For example, you push a child in a swing to get the motion started.","Newton’s first law implies that an object oscillating back and forth is experiencing forces. Without force, the object would move in a straight line at a constant speed rather than oscillate. Consider, for example, plucking a plastic ruler to the left as shown in [Figure 5.5]. The deformation of the ruler creates a force in the opposite direction, known as a restoring force . Once released, the restoring force causes the ruler to move back toward its stable equilibrium position, where the net force on it is zero. However, by the time the ruler gets there, it gains momentum and continues to move to the right, producing the opposite deformation. It is then forced to the left, back through equilibrium, and the process is repeated until it gradually loses all of its energy. The simplest oscillations occur when the restoring force is directly proportional to displacement. Recall that Hooke’s law describes this situation with the equation F = - kx . Therefore, Hooke’s law describes and applies to the simplest case of oscillation, known as simple harmonic motion .","When you pluck a guitar string, the resulting sound has a steady tone and lasts a long time. Each vibration of the string takes the same time as the previous one. Periodic motion is a motion that repeats itself at regular time intervals, such as with an object bobbing up and down on a spring or a pendulum swinging back and forth. The time to complete one oscillation (a complete cycle of motion) remains constant and is called the period T . Its units are usually seconds.","Frequency f is the number of oscillations per unit time. The SI unit for frequency is the hertz (Hz), defined as the number of oscillations per second. The relationship between frequency and period is","As you can see from the equation, frequency and period are different ways of expressing the same concept. For example, if you get a paycheck twice a month, you could say that the frequency of payment is two per month, or that the period between checks is half a month.","If there is no friction to slow it down, then an object in simple motion will oscillate forever with equal displacement on either side of the equilibrium position. The equilibrium position is where the object would naturally rest in the absence of force. The maximum displacement from equilibrium is called the amplitude X . The units for amplitude and displacement are the same, but depend on the type of oscillation. For the object on the spring, shown in [Figure 5.5], the units of amplitude and displacement are meters.","The mass m and the force constant k are the only factors that affect the period and frequency of simple harmonic motion. The period of a simple harmonic oscillator is given by","and, because f = 1/ T , the frequency of a simple harmonic oscillator is"],"figures":[{"sourceId":"fs-id1167066867658","filename":"CNX_HSPhysics_05_05_ruler.jpg","relativePath":"media/CNX_HSPhysics_05_05_ruler.jpg","alt":"A drawing is shown of hands holding and flicking an upright ruler. A double-ended arrow is shown over the ruler and a label Equilibrium position points to the upright position of the ruler."},{"sourceId":"fs-id1167067110350","filename":"CNX_HSPhysics_05_05_equilibrium.jpg","relativePath":"media/CNX_HSPhysics_05_05_equilibrium.jpg","alt":"Four diagrams are shown, side-by-side, labeled a, b, c, d, and e. They show the sideways motion of a ruler that has been flicked. The vertical position of the ruler is labeled equilibrium position. A right-pointing force vector is shown on diagram a. A right-facing velocity vector and F equals zero is shown on b. A left-pointing force vector is shown on diagram c. A left-facing velocity vector and F equals zero is shown on d. A right-pointing force vector is shown on diagram e."},{"sourceId":"fs-id1167066824914","filename":"CNX_HSPhysics_05_05_object.jpg","relativePath":"media/CNX_HSPhysics_05_05_object.jpg","alt":"Five diagrams, a, b, c, d, and e are shown. They show an object attached to a spring sliding on a frictionless surface. Diagram a shows a left-pointing force vector and the following labels: v equals zero, x equals zero, x equals x, k. Diagram b has the following labels: F equals zero, negative v max, x equals zero. Diagram c shows a right-pointing force vector and the following labels: v equals zero, x equals zero, x equals negative x. Diagram d has the following labels: F equals zero, positive v max, x equals zero. Diagram e shows a left-pointing force vector and the following labels: v equals zero, x equals zero, x equals x. Free-body diagrams illustrate the forces acting on each system."}],"tables":[]},{"uid":"hsphys.ch05.sec05.sub03","title":"Solving Spring and Pendulum Problems with Simple Harmonic Motion","summaryVi":null,"paragraphs":["Before solving problems with springs and pendulums, it is important to first get an understanding of how a pendulum works. [Figure 5.5] provides a useful illustration of a simple pendulum.","Everyday examples of pendulums include old-fashioned clocks, a child’s swing, or the sinker on a fishing line. For small displacements of less than 15 degrees, a pendulum experiences simple harmonic oscillation, meaning that its restoring force is directly proportional to its displacement. A pendulum in simple harmonic motion is called a simple pendulum . A pendulum has an object with a small mass, also known as the pendulum bob, which hangs from a light wire or string. The equilibrium position for a pendulum is where the angle \\(\\theta\\) is zero (that is, when the pendulum is hanging straight down). It makes sense that without any force applied, this is where the pendulum bob would rest.","The displacement of the pendulum bob is the arc length s . The weight m g has components m g cos \\(\\theta\\) along the string and m g sin \\(\\theta\\) tangent to the arc. Tension in the string exactly cancels the component m g cos \\(\\theta\\) parallel to the string. This leaves a net restoring force back toward the equilibrium position that runs tangent to the arc and equals - m g sin \\(\\theta\\) .","For small angle oscillations of a simple pendulum, the period is \\(T = 2\\pi \\sqrt{\\frac{L}{\\mathbf{g}}}.\\)","The only things that affect the period of a simple pendulum are its length and the acceleration due to gravity. The period is completely independent of other factors, such as mass or amplitude. However, note that T does depend on g . This means that if we know the length of a pendulum, we can actually use it to measure gravity! This will come in useful in [Worked_Example_05_09]."],"figures":[{"sourceId":"fs-id1167066975444","filename":"CNX_HSPhysics_05_05_pendulum.jpg","relativePath":"media/CNX_HSPhysics_05_05_pendulum.jpg","alt":"A pendulum is shown with a small-diameter bob and a string that has a very small mass but is strong enough not to stretch. The linear displacement from equilibrium is labeled s, the length of the arc. Also shown are the forces on the bob, which result in a net force of  negative m times g sine angle toward the equilibrium position."}],"tables":[]},{"uid":"hsphys.ch05.sec05.sub04","title":"Performance Task","summaryVi":null,"paragraphs":["Construct a seconds pendulum (pendulum with time period 2 seconds)."],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch05.sec05.ex01","number":"5.5.1","title":"Measuring Acceleration due to Gravity: The Period of a Pendulum","problem":"What is the acceleration due to gravity in a region where a simple pendulum having a length 75.000 cm has a period of 1.7357 s?","problemImages":[],"strategy":"We are asked to find g given the period T and the length L of a pendulum. We can solve \\(T = 2\\pi \\sqrt{\\frac{L}{\\mathbf{g}}}\\) for g , assuming that the angle of deflection is less than 15 degrees. Recall that when the angle of deflection is less than 15 degrees, the pendulum is considered to be in simple harmonic motion, allowing us to use this equation.","solution":"Square \\(T = 2\\pi \\sqrt{\\frac{L}{\\mathbf{g}}}\\) and solve for g .\n\\(\\mathbf{g} = 4{\\pi}^{2}\\frac{L}{{T}^{2}}\\)\nSubstitute known values into the new equation.\n\\(\\mathbf{g} = 4{\\pi}^{2}\\frac{0.75000\\,\\text{m}}{{(1.7357\\,\\text{s})}^{2}}\\)\nCalculate to find g .\n\\(\\mathbf{g} = 9.8281\\,\\text{m}/{\\text{s}}^{2}\\)","solutionImages":[],"solutionTables":[],"discussion":"This method for determining g can be very accurate. This is why length and period are given to five digits in this example."},{"uid":"hsphys.ch05.sec05.ex02","number":"5.5.2","title":"Hooke’s Law: How Stiff Are Car Springs?","problem":"What is the force constant for the suspension system of a car, like that shown in [Figure 5.5], that settles 1.20 cm when an 80.0-kg person gets in?\nA car in a parking lot. (exfordy, Flickr)","problemImages":[{"sourceId":"fs-id1167066845053","filename":"CNX_HSPhysics_05_05_car.jpg","relativePath":"media/CNX_HSPhysics_05_05_car.jpg","alt":"A side view of the back end of a blue compact car is shown. The car is sitting on black asphalt."}],"strategy":"Consider the car to be in its equilibrium position x = 0 before the person gets in. The car then settles down 1.20 cm, which means it is displaced to a position x = -1.20×10 -2 m.\nAt that point, the springs supply a restoring force F equal to the person’s weight\nw = m g = (80.0 kg)(9.80 m/s 2 ) = 784 N. We take this force to be F in Hooke’s law.\nKnowing F and x , we can then solve for the force constant k .","solution":"Solve Hooke’s law, F = - kx , for k .\n\\(\\mathbf{k} = \\frac{\\mathbf{F}}{\\mathbf{x}}\\)\nSubstitute known values and solve for k .\n\\(\\mathbf{k} = \\frac{- 784\\,\\text{N}}{- 1.20 \\times {10}^{- 2}\\text{m}} = 6.53 \\times {10}^{4}\\text{N/m}\\)","solutionImages":[],"solutionTables":[],"discussion":"Note that F and x have opposite signs because they are in opposite directions—the restoring force is up, and the displacement is down. Also, note that the car would oscillate up and down when the person got in, if it were not for the shock absorbers. Bouncing cars are a sure sign of bad shock absorbers."}],"snapLabs":[{"uid":"hsphys.ch05.sec05.lab01","title":"Finding Gravity Using a Simple Pendulum","text":"Use a simple pendulum to find the acceleration due to gravity g in your home or classroom.\n1 string\n1 stopwatch\n1 small dense object\nCut a piece of a string or dental floss so that it is about 1 m long.\nAttach a small object of high density to the end of the string (for example, a metal nut or a car key).\nStarting at an angle of less than 10 degrees, allow the pendulum to swing and measure the pendulum’s period for 10 oscillations using a stopwatch.\nCalculate g .","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch05.sec05.feat01","type":"tip","title":"Tips for Success","text":"Tension is represented by the variable T , and period is represented by the variable T . It is important not to confuse the two, since tension is a force and period is a length of time.","images":[]}],"summaryPoints":["An oscillation is a back and forth motion of an object between two points of deformation.","The simplest type of oscillations are related to systems that can be described by Hooke’s law.","Periodic motion is a repetitious oscillation.","The time for one oscillation is the period T.","The number of oscillations per unit time is the frequency","A mass m suspended by a wire of length L is a simple pendulum and undergoes simple harmonic motion for amplitudes less than about 15 degrees."],"glossary":[{"term":"amplitude","termVi":"Biên độ dao động (A)","definition":"the maximum displacement from the equilibrium position of an object oscillating around the equilibrium position","definitionVi":"Độ lệch cực đại so với vị trí cân bằng.","memoryTipVi":"Đơn vị độ dài (m)."},{"term":"deformation","termVi":"Sự biến dạng","definition":"displacement from equilibrium, or change in shape due to the application of force","definitionVi":"Sự thay đổi hình dạng/kích thước của vật (như lò xo dãn/nén Δx).","memoryTipVi":"Biến dạng đàn hồi tuân theo Định luật Hooke."},{"term":"equilibrium position","termVi":"Vị trí cân bằng (VTCB)","definition":"where an object would naturally rest in the absence of a net force","definitionVi":"Vị trí tại đó hợp lực tác dụng lên vật bằng 0.","memoryTipVi":"Tại VTCB, vận tốc dao động đạt cực đại."},{"term":"frequency","termVi":"Tần số (f)","definition":"number of events per unit of time","definitionVi":"Số dao động toàn phần thực hiện trong 1 giây (đơn vị Hertz, Hz): f = 1/T.","memoryTipVi":"1 Hz = 1 dao động/giây."},{"term":"Hooke’s law","termVi":"Định luật Hooke (Lực đàn hồi lò xo)","definition":"proportional relationship between the force F on a material and the deformation \\(\\Delta L\\) it causes, \\(\\mathbf{F} = \\mathbf{k}\\Delta L\\)","definitionVi":"Lực đàn hồi tỉ lệ thuận với độ biến dạng và ngược chiều biến dạng: F = -kx.","memoryTipVi":"k là độ cứng lò xo (N/m)."},{"term":"oscillate","termVi":"Dao động qua lại","definition":"moving back and forth regularly between two points","definitionVi":"Chuyển động lặp đi lặp lại quanh một vị trí cân bằng.","memoryTipVi":"Oscillation = sự dao động."},{"term":"period","termVi":"Chu kỳ dao động (T)","definition":"time it takes to complete one oscillation","definitionVi":"Thời gian để vật thực hiện đúng 1 dao động toàn phần (đơn vị giây, s): T = 1/f.","memoryTipVi":"Chu kỳ con lắc đơn T = 2π√(L/g)."},{"term":"periodic motion","termVi":"Chuyển động tuần hoàn","definition":"motion that repeats itself at regular time intervals","definitionVi":"Chuyển động tự lặp lại trạng thái sau những khoảng thời gian bằng nhau.","memoryTipVi":"Ví dụ: kim đồng hồ, Trái Đất quay quanh Mặt Trời."},{"term":"restoring force","termVi":"Lực kéo về (Lực hồi phục)","definition":"force acting in opposition to the force causing the deformation","definitionVi":"Hợp lực luôn hướng về vị trí cân bằng để kéo vật trở lại.","memoryTipVi":"Trong con lắc lò xo: F_kv = -kx."},{"term":"simple harmonic motion","termVi":"Dao động điều hòa (SHM)","definition":"the oscillatory motion in a system where the net force can be described by Hooke’s law","definitionVi":"Dao động tuần hoàn mà lực kéo về tỉ lệ thuận với li độ và hướng về VTCB (F = -kx).","memoryTipVi":"Viết tắt quốc tế: SHM."},{"term":"simple pendulum","termVi":"Con lắc đơn","definition":"an object with a small mass suspended from a light wire or string","definitionVi":"Vật nhỏ treo ở đầu sợi dây không dãn khối lượng không đáng kể dao động dưới trọng lực.","memoryTipVi":"Chu kỳ T = 2π√(L/g) KHÔNG phụ thuộc vào khối lượng vật nặng!"}],"assessments":[{"uid":"hsphys.ch05.sec05.q002","sourceId":"fs-id1167066825346","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"According to Hookes law, what is deformation proportional to?","images":[],"choices":[{"label":"a","text":"Force"},{"label":"b","text":"Velocity"},{"label":"c","text":"Displacement"},{"label":"d","text":"Force constant"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec05.q003","sourceId":"fs-id1167066867310","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What are oscillations?","images":[],"choices":[{"label":"a","text":"Motion resulting in small displacements"},{"label":"b","text":"Motion which repeats itself periodically"},{"label":"c","text":"Periodic, repetitive motion between two points"},{"label":"d","text":"motion that is the opposite to the direction of the restoring force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec05.q004","sourceId":"fs-id1167067028710","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"True or FalseOscillations can occur without force.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec05.q008","sourceId":"fs-id1167066971744","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"With reference to simple harmonic motion, what is the equilibrium position?","images":[],"choices":[{"label":"a","text":"The position where velocity is the minimum"},{"label":"b","text":"The position where the displacement is maximum"},{"label":"c","text":"The position where the restoring force is the maximum"},{"label":"d","text":"The position where the object rests in the absence of force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec05.q010","sourceId":"fs-id1167066880063","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Two springs are attached to two hooks. Spring A has a greater force constant than spring B. Equal weights are suspended from both. Which of the following statements is true?","images":[],"choices":[{"label":"a","text":"Spring A will have more extension than spring B."},{"label":"b","text":"Spring B will have more extension than spring A."},{"label":"c","text":"Both springs will have equal extension."},{"label":"d","text":"Both springs are equally stiff."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec05.q016","sourceId":"fs-id1167066880217","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A change in which of the following is an example of deformation?","images":[],"choices":[{"label":"a","text":"Velocity"},{"label":"b","text":"Length"},{"label":"c","text":"Mass"},{"label":"d","text":"Weight"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec05.q017","sourceId":"fs-id1167066868011","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"The units of amplitude are the same as those for which of the following measurements?","images":[],"choices":[{"label":"a","text":"Speed"},{"label":"b","text":"Displacement"},{"label":"c","text":"Acceleration"},{"label":"d","text":"Force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec05.q021","sourceId":"fs-id1167066836651","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What is the term used for changes in shape due to the application of force?","images":[],"choices":[{"label":"a","text":"Amplitude"},{"label":"b","text":"Deformation"},{"label":"c","text":"Displacement"},{"label":"d","text":"Restoring force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec05.q022","sourceId":"fs-id1167066799540","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What is the restoring force?","images":[],"choices":[{"label":"a","text":"The normal force on the surface of an object"},{"label":"b","text":"The weight of a mass attached to an object"},{"label":"c","text":"Force which is applied to deform an object from its original shape"},{"label":"d","text":"Force which brings an object back to its equilibrium position"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec05.q023","sourceId":"fs-id1167066846439","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"For a given oscillator, what are the factors that affect its period and frequency?","images":[],"choices":[{"label":"a","text":"Mass only"},{"label":"b","text":"Force constant only"},{"label":"c","text":"Applied force and mass"},{"label":"d","text":"Mass and force constant"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec05.q024","sourceId":"fs-id1167066880928","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"For an object in simple harmonic motion, when does the maximum speed occur?","images":[],"choices":[{"label":"a","text":"At the extreme positions"},{"label":"b","text":"At the equilibrium position"},{"label":"c","text":"At the moment when the applied force is removed"},{"label":"d","text":"Midway between the extreme and equilibrium positions"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec05.q025","sourceId":"fs-id1167067092323","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What is the equilibrium position of a pendulum?","images":[],"choices":[{"label":"a","text":"When the tension in the string is zero"},{"label":"b","text":"When the pendulum is hanging straight down"},{"label":"c","text":"When the tension in the string is maximum"},{"label":"d","text":"When the weight of the mass attached is minimum"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec05.q026","sourceId":"fs-id1167067083339","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"If a pendulum is displaced by an angle θ , what is the net restoring force it experiences?","images":[],"choices":[{"label":"a","text":"mg sin θ"},{"label":"b","text":"mg cos θ"},{"label":"c","text":"– mg sin θ"},{"label":"d","text":"– mg cos θ"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch05.sec05.q027","sourceId":"fs-id1167066833959","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"What physical characteristic of a system is its force constant related to?","images":[],"choices":[{"label":"a","text":"The force constant k is related to the stiffness of a system: The larger the force constant, the stiffer the system."},{"label":"b","text":"The force constant k is related to the stiffness of a system: The larger the force constant, the looser the system."},{"label":"c","text":"The force constant k is related to the friction in the system: The larger the force constant, the greater the friction in the system."},{"label":"d","text":"The force constant k is related to the friction in the system: The larger the force constant, the lower the friction in the system."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":3,"keyEquationCount":4,"subsectionCount":4,"workedExampleCount":2,"snapLabCount":1,"glossaryCount":11,"assessmentCount":14}}],"summary":{"totalSections":6,"totalKeyEquations":18,"totalWorkedExamples":10,"totalSnapLabs":2,"totalGlossaryTerms":28,"totalAssessments":55,"referencedMediaCount":38},"qualityGate":{"passed":true,"checkedUids":89,"errors":[],"warnings":[]}};
